from (values
(386130,42904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, er hat mir erzählt, er ... sein Getränk, als ihr Zug ihn geschockt hat.'::text,'trank gerade'::text,'trank'::text,'hat getrunken'::text,'Omg, er hat mir erzählt, er trank gerade sein Getränk, als ihr Zug ihn geschockt hat.'::text),
(386134,42904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Омг, він сказав мені, що ... свій напій, коли її хід його шокував.'::text,'пив'::text,'випив'::text,'випив'::text,'Омг, він сказав мені, що пив свій напій, коли її хід його шокував.'::text),
(386133,42904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, me dijo que ... su bebida cuando su jugada lo dejó en shock.'::text,'estaba tomando'::text,'tomó'::text,'ha tomado'::text,'Dios, me dijo que estaba tomando su bebida cuando su jugada lo dejó en shock.'::text),
(386132,42904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, il m''a dit qu''il ... sa boisson quand son coup l''a bluffé.'::text,'était en train de boire'::text,'a bu'::text,'a bu'::text,'Omg, il m''a dit qu''il était en train de boire sa boisson quand son coup l''a bluffé.'::text),
(386135,42904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman Tanrım, bana anlattı: kızın hamlesi onu şoke ettiğinde içeceğini ...'::text,'içiyormuş'::text,'içmiş'::text,'içmiş'::text,'Aman Tanrım, bana anlattı: kızın hamlesi onu şoke ettiğinde içeceğini içiyormuş.'::text),
(386136,42904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, azt mondta, hogy épp ... az italát, amikor a lány lépése sokkolta.'::text,'itta'::text,'megitta'::text,'megitta'::text,'Omg, azt mondta, hogy épp itta az italát, amikor a lány lépése sokkolta.'::text),
(386139,42905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... ihn den ganzen Abend mit cleveren Zügen, und ehrlich, Respekt.'::text,'schockst'::text,'schockst'::text,'schockst'::text,'Du schockst ihn den ganzen Abend mit cleveren Zügen, und ehrlich, Respekt.'::text),
(386143,42905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... його хитрими ходами весь вечір, і чесно, респект.'::text,'шокуєш'::text,'шокуєш'::text,'шокуєш'::text,'Ти шокуєш його хитрими ходами весь вечір, і чесно, респект.'::text),
(386142,42905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... toda la noche con jugadas brillantes, y la verdad, respeto.'::text,'Lo has estado dejando en shock'::text,'Lo estás dejando en shock'::text,'Lo dejas en shock'::text,'Lo has estado dejando en shock toda la noche con jugadas brillantes, y la verdad, respeto.'::text),
(386141,42905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu le ... avec des coups malins toute la soirée, et franchement, respect.'::text,'bluffes'::text,'bluffes'::text,'bluffes'::text,'Tu le bluffes avec des coups malins toute la soirée, et franchement, respect.'::text),
(386144,42905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün akşam zekice hamlelerle onu ... ve açıkçası, helal olsun.'::text,'şoke ediyorsun'::text,'şoke ediyorsun'::text,'şoke edersin'::text,'Bütün akşam zekice hamlelerle onu şoke ediyorsun ve açıkçası, helal olsun.'::text),
(386145,42905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész este ... okos lépésekkel, és őszintén, respekt.'::text,'sokkolod'::text,'sokkolod'::text,'sokkolod'::text,'Egész este sokkolod okos lépésekkel, és őszintén, respekt.'::text),
(386157,42907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Fokus, klar. Ihr Zug ..., hätte er aufs Brett geschaut.'::text,'hätte ihn nicht geschockt'::text,'wird ihn nicht schocken'::text,'schockte ihn nicht'::text,'Toller Fokus, klar. Ihr Zug hätte ihn nicht geschockt, hätte er aufs Brett geschaut.'::text),
(386161,42907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова зосередженість, звісно. Якби він дивився на дошку, її хід ...'::text,'не шокував би його'::text,'не шокує його'::text,'не шокував його'::text,'Чудова зосередженість, звісно. Якби він дивився на дошку, її хід не шокував би його.'::text),
(386160,42907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué concentración, obviamente. Si hubiera mirado el tablero, su jugada ...'::text,'no lo habría dejado en shock'::text,'no lo dejará en shock'::text,'no lo dejó en shock'::text,'Qué concentración, obviamente. Si hubiera mirado el tablero, su jugada no lo habría dejado en shock.'::text),
(386159,42907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super concentration, évidemment. S''il avait regardé le plateau, son coup ...'::text,'ne l''aurait pas bluffé'::text,'ne le bluffera pas'::text,'ne l''a pas bluffé'::text,'Super concentration, évidemment. S''il avait regardé le plateau, son coup ne l''aurait pas bluffé.'::text),
(386162,42907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika odak, tabii. Tahtaya baksaydı, kızın hamlesi onu ...'::text,'şoke etmezdi'::text,'şoke etmeyecek'::text,'şoke etmedi'::text,'Harika odak, tabii. Tahtaya baksaydı, kızın hamlesi onu şoke etmezdi.'::text),
(386163,42907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek koncentráció, persze. Ha a táblát nézte volna, a lány lépése ...'::text,'nem sokkolta volna'::text,'nem fogja sokkolni'::text,'nem sokkolta'::text,'Remek koncentráció, persze. Ha a táblát nézte volna, a lány lépése nem sokkolta volna.'::text),
(386166,42908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er warf ihr vor, ihn mit einem geheimen Zug ...'::text,'geschockt zu haben'::text,'zu schocken'::text,'geschockt'::text,'Er warf ihr vor, ihn mit einem geheimen Zug geschockt zu haben.'::text),
(386170,42908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він звинуватив її в тому, що вона ... його таємним ходом.'::text,'шокувала'::text,'шокувала'::text,'шокувала'::text,'Він звинуватив її в тому, що вона шокувала його таємним ходом.'::text),
(386169,42908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La acusó de ... con una jugada secreta.'::text,'dejarlo en shock'::text,'dejarlo en shock'::text,'haberlo dejado en shock'::text,'La acusó de dejarlo en shock con una jugada secreta.'::text),
(386168,42908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il l''a accusée de ... avec un coup secret.'::text,'l''avoir bluffé'::text,'le bluffer'::text,'bluffé'::text,'Il l''a accusée de l''avoir bluffé avec un coup secret.'::text),
(386171,42908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızı onu gizli bir hamleyle ... suçladı.'::text,'şoke etmekle'::text,'şoke etmekle'::text,'şoke etmekle'::text,'Kızı onu gizli bir hamleyle şoke etmekle suçladı.'::text),
(386172,42908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azzal vádolta a lányt, hogy egy titkos lépéssel ... őt.'::text,'sokkolta'::text,'sokkolta'::text,'sokkolta'::text,'Azzal vádolta a lányt, hogy egy titkos lépéssel sokkolta őt.'::text),
(386175,42909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ...; dann hätte ihr Zug ihn nicht geschockt.'::text,'hätte aufs Brett schauen sollen'::text,'muss aufs Brett geschaut haben'::text,'konnte aufs Brett schauen'::text,'Er hätte aufs Brett schauen sollen; dann hätte ihr Zug ihn nicht geschockt.'::text),
(386179,42909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на дошку; тоді її хід не шокував би його.'::text,'мав дивитися'::text,'напевно дивився'::text,'міг дивитися'::text,'Він мав дивитися на дошку; тоді її хід не шокував би його.'::text),
(386178,42909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el tablero; así su jugada no lo habría dejado en shock.'::text,'Debería haber mirado'::text,'Debe de haber mirado'::text,'Podía mirar'::text,'Debería haber mirado el tablero; así su jugada no lo habría dejado en shock.'::text),
(386177,42909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le plateau ; comme ça, son coup ne l''aurait pas bluffé.'::text,'aurait dû regarder'::text,'a dû regarder'::text,'pouvait regarder'::text,'Il aurait dû regarder le plateau ; comme ça, son coup ne l''aurait pas bluffé.'::text),
(386180,42909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahtaya ...; o zaman kızın hamlesi onu şoke etmezdi.'::text,'bakmalıydı'::text,'bakmış olmalı'::text,'bakabilirdi'::text,'Tahtaya bakmalıydı; o zaman kızın hamlesi onu şoke etmezdi.'::text),
(386181,42909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a táblát; akkor a lány lépése nem sokkolta volna.'::text,'Figyelnie kellett volna'::text,'Biztosan figyelte'::text,'Figyelhette'::text,'Figyelnie kellett volna a táblát; akkor a lány lépése nem sokkolta volna.'::text),
(386184,42910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie brachte ihn dazu, vom Brett ..., und schockte ihn dann mit ihrem Zug.'::text,'wegzuschauen'::text,'wegschauen'::text,'wegschauend'::text,'Sie brachte ihn dazu, vom Brett wegzuschauen, und schockte ihn dann mit ihrem Zug.'::text),
(386188,42910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона змусила його ... від дошки, а потім шокувала своїм ходом.'::text,'відвести погляд'::text,'відвести погляд'::text,'відводячи погляд'::text,'Вона змусила його відвести погляд від дошки, а потім шокувала своїм ходом.'::text),
(386187,42910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizo que ... del tablero y luego lo dejó en shock con su jugada.'::text,'apartara la vista'::text,'apartara la vista'::text,'apartando la vista'::text,'Hizo que apartara la vista del tablero y luego lo dejó en shock con su jugada.'::text),
(386186,42910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle l''a poussé à ... du plateau, puis l''a bluffé avec son coup.'::text,'détourner les yeux'::text,'détourner les yeux'::text,'détournant les yeux'::text,'Elle l''a poussé à détourner les yeux du plateau, puis l''a bluffé avec son coup.'::text),
(386189,42910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun tahtadan ... sağladı, sonra hamlesiyle onu şoke etti.'::text,'gözünü ayırmasını'::text,'gözünü ayırmasını'::text,'gözünü ayırarak'::text,'Onun tahtadan gözünü ayırmasını sağladı, sonra hamlesiyle onu şoke etti.'::text),
(386190,42910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rávette, hogy ... a tábláról, aztán sokkolta a lépésével.'::text,'elnézzen'::text,'elnézzen'::text,'elnézve'::text,'Rávette, hogy elnézzen a tábláról, aztán sokkolta a lépésével.'::text),
(386193,42911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, er ..., bevor ihr Zug ihn für immer geschockt hat!'::text,'hätte aufs Brett geschaut'::text,'schaute aufs Brett'::text,'würde aufs Brett schauen'::text,'Er wünscht sich, er hätte aufs Brett geschaut, bevor ihr Zug ihn für immer geschockt hat!'::text),
(386197,42911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би тоді ... на дошку, перш ніж її хід навіки його шокував!'::text,'подивитися'::text,'подивитися'::text,'подивитися'::text,'Він хотів би тоді подивитися на дошку, перш ніж її хід навіки його шокував!'::text),
(386196,42911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desearía ... el tablero antes de que su jugada lo dejara en shock para siempre!'::text,'haber mirado'::text,'mirar'::text,'mirar'::text,'¡Él desearía haber mirado el tablero antes de que su jugada lo dejara en shock para siempre!'::text),
(386195,42911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voudrait ... le plateau avant que son coup ne le bluffe à jamais !'::text,'avoir regardé'::text,'regarder'::text,'regarder'::text,'Il voudrait avoir regardé le plateau avant que son coup ne le bluffe à jamais !'::text),
(386198,42911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke kızın hamlesi onu sonsuza dek şoke etmeden önce tahtaya ... diyor!'::text,'baksaydım'::text,'baksam'::text,'bakardım'::text,'Keşke kızın hamlesi onu sonsuza dek şoke etmeden önce tahtaya baksaydım diyor!'::text),
(386199,42911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... a táblára, mielőtt a lány lépése örökre sokkolta!'::text,'ránézett volna'::text,'ránézett'::text,'ránézne'::text,'Azt kívánja, bárcsak ránézett volna a táblára, mielőtt a lány lépése örökre sokkolta!'::text),
(386202,42912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zug, ... ihn völlig geschockt hat, hat seine ganze Armee vernichtet!'::text,'der'::text,'der'::text,'was'::text,'Der Zug, der ihn völlig geschockt hat, hat seine ganze Armee vernichtet!'::text),
(386206,42912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хід, ... повністю його шокував, знищив усю його армію!'::text,'який'::text,'який'::text,'що'::text,'Хід, який повністю його шокував, знищив усю його армію!'::text),
(386205,42912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La jugada, ... lo dejó en shock total, destruyó todo su ejército!'::text,'la cual'::text,'que'::text,'lo que'::text,'¡La jugada, la cual lo dejó en shock total, destruyó todo su ejército!'::text),
(386204,42912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coup, ... l''a complètement bluffé, a détruit toute son armée !'::text,'qui'::text,'qui'::text,'ce qui'::text,'Le coup, qui l''a complètement bluffé, a détruit toute son armée !'::text),
(386207,42912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O hamle, ... onu tamamen şoke etti, bütün ordusunu yok etti!'::text,'ki'::text,'ki'::text,'ne'::text,'O hamle, ki onu tamamen şoke etti, bütün ordusunu yok etti!'::text),
(386208,42912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lépés, ... teljesen sokkolta, az egész seregét elpusztította!'::text,'amely'::text,'amely'::text,'ami'::text,'A lépés, amely teljesen sokkolta, az egész seregét elpusztította!'::text),
(386211,42913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie verschob ihre Figuren leise, ... ihn zu schocken, als er wieder hinsah.'::text,'um'::text,'damit'::text,'um'::text,'Sie verschob ihre Figuren leise, um ihn zu schocken, als er wieder hinsah.'::text),
(386215,42913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тихо пересунула свої фігури, ... шокувати його, коли він знову подивився.'::text,'щоб'::text,'щоб'::text,'для того'::text,'Вона тихо пересунула свої фігури, щоб шокувати його, коли він знову подивився.'::text),
(386214,42913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Movió sus fichas en silencio ... dejarlo en shock cuando volviera a mirar.'::text,'para'::text,'para que'::text,'con el fin'::text,'Movió sus fichas en silencio para dejarlo en shock cuando volviera a mirar.'::text),
(386213,42913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a déplacé ses pions en silence ... le bluffer quand il a regardé de nouveau.'::text,'pour'::text,'pour que'::text,'afin'::text,'Elle a déplacé ses pions en silence pour le bluffer quand il a regardé de nouveau.'::text),
(386216,42913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekrar baktığında onu şoke etmek ... taşlarını sessizce oynattı.'::text,'için'::text,'diye'::text,'amacıyla'::text,'Tekrar baktığında onu şoke etmek için taşlarını sessizce oynattı.'::text),
(386217,42913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csendben elmozdította a bábuit, ... sokkolja őt, amikor visszanéz.'::text,'hogy'::text,'úgyhogy'::text,'azért'::text,'Csendben elmozdította a bábuit, hogy sokkolja őt, amikor visszanéz.'::text),
(352182,39132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Seeufer war weit weg, und ...'::text,'die Canyonklippen auch.'::text,'die Canyonklippen auch.'::text,'die Canyonklippen auch nicht.'::text,'Das Seeufer war weit weg, und die Canyonklippen auch.'::text),
(352186,39132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Берег озера був далеко, і ...'::text,'скелі каньйону теж.'::text,'скелі каньйону теж.'::text,'скелі каньйону ні.'::text,'Берег озера був далеко, і скелі каньйону теж.'::text),
(352185,39132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La orilla del lago estaba lejos, y ...'::text,'los acantilados del cañón también.'::text,'los acantilados del cañón también.'::text,'los acantilados del cañón tampoco.'::text,'La orilla del lago estaba lejos, y los acantilados del cañón también.'::text),
(352184,39132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rive du lac était loin, et ...'::text,'les falaises du canyon aussi.'::text,'les falaises du canyon aussi.'::text,'les falaises du canyon non plus.'::text,'La rive du lac était loin, et les falaises du canyon aussi.'::text),
(352187,39132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Göl kıyısı uzaktaydı ve ...'::text,'kanyon kayalıkları da öyleydi.'::text,'kanyon kayalıkları da öyleydi.'::text,'kanyon kayalıkları da değildi.'::text,'Göl kıyısı uzaktaydı ve kanyon kayalıkları da öyleydi.'::text),
(352188,39132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tópart messze volt, és ...'::text,'a kanyon sziklái is.'::text,'a kanyon sziklái is.'::text,'a kanyon sziklái sem.'::text,'A tópart messze volt, és a kanyon sziklái is.'::text),
(352191,39133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird sie jede ferne Klippe in diesem Canyon ..., sonst ist es eine Katastrophe!'::text,'gesehen haben'::text,'sehen'::text,'am Sehen sein'::text,'Bis Sonnenuntergang wird sie jede ferne Klippe in diesem Canyon gesehen haben, sonst ist es eine Katastrophe!'::text),
(352195,39133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вона ... кожну далеку скелю в цьому каньйоні, інакше це катастрофа!'::text,'побачить'::text,'побачить'::text,'бачитиме'::text,'До заходу сонця вона побачить кожну далеку скелю в цьому каньйоні, інакше це катастрофа!'::text),
(352194,39133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer ya ... todos los acantilados lejanos de este cañón, o es un desastre!'::text,'habrá visto'::text,'verá'::text,'estará viendo'::text,'¡Para el atardecer ya habrá visto todos los acantilados lejanos de este cañón, o es un desastre!'::text),
(352193,39133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, elle ... chaque falaise lointaine de ce canyon, sinon c''est la catastrophe !'::text,'aura vu'::text,'verra'::text,'sera en train de voir'::text,'D''ici le coucher du soleil, elle aura vu chaque falaise lointaine de ce canyon, sinon c''est la catastrophe !'::text),
(352196,39133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu kanyondaki her uzak kayalığı ..., yoksa felaket!'::text,'görmüş olacak'::text,'görecek'::text,'görüyor olacak'::text,'Gün batımına kadar bu kanyondaki her uzak kayalığı görmüş olacak, yoksa felaket!'::text),
(352197,39133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére ... ennek a kanyonnak minden távoli szikláját, különben katasztrófa!'::text,'látni fogja'::text,'látni fogja'::text,'nézni fogja'::text,'Naplementére látni fogja ennek a kanyonnak minden távoli szikláját, különben katasztrófa!'::text),
(352200,39134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre das Ufer nicht so weit weg gewesen, hätte sie dieses Fernglas überhaupt ...! Ein Albtraum!'::text,'nicht gebraucht'::text,'nicht brauchen'::text,'nicht gebraucht'::text,'Wäre das Ufer nicht so weit weg gewesen, hätte sie dieses Fernglas überhaupt nicht gebraucht! Ein Albtraum!'::text),
(352204,39134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби берег не був так далеко, їй ... той бінокль узагалі! Кошмар!'::text,'не знадобився б'::text,'не знадобиться'::text,'не знадобився'::text,'Якби берег не був так далеко, їй не знадобився б той бінокль узагалі! Кошмар!'::text),
(352203,39134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la orilla no hubiera estado tan lejos, ... esos prismáticos para nada! ¡Una pesadilla!'::text,'no habría necesitado'::text,'no necesitará'::text,'no necesitó'::text,'¡Si la orilla no hubiera estado tan lejos, no habría necesitado esos prismáticos para nada! ¡Una pesadilla!'::text),
(352202,39134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rive n''avait pas été si loin, elle ... ces jumelles du tout ! Un cauchemar !'::text,'n''aurait pas eu besoin de'::text,'n''aura pas besoin de'::text,'n''a pas eu besoin de'::text,'Si la rive n''avait pas été si loin, elle n''aurait pas eu besoin de ces jumelles du tout ! Un cauchemar !'::text),
(352205,39134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyı o kadar uzak olmasaydı, o dürbüne hiç ...! Tam bir kâbus!'::text,'ihtiyaç duymazdı'::text,'ihtiyaç duymayacak'::text,'ihtiyaç duymadı'::text,'Kıyı o kadar uzak olmasaydı, o dürbüne hiç ihtiyaç duymazdı! Tam bir kâbus!'::text),
(352206,39134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a part nem lett volna ilyen messze, egyáltalán ... arra a távcsőre! Rémálom!'::text,'nem lett volna szüksége'::text,'nem lesz szüksége'::text,'nem volt szüksége'::text,'Ha a part nem lett volna ilyen messze, egyáltalán nem lett volna szüksége arra a távcsőre! Rémálom!'::text),
(352209,39135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich hat sie abgestritten, etwas am fernen Ufer ...'::text,'gesehen zu haben'::text,'gesehen zu haben'::text,'zu sehen'::text,'Hör mal, angeblich hat sie abgestritten, etwas am fernen Ufer gesehen zu haben.'::text),
(352213,39135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона заперечила, що ... щось на далекому березі.'::text,'бачила'::text,'бачила'::text,'бачить'::text,'Слухай, кажуть, вона заперечила, що бачила щось на далекому березі.'::text),
(352212,39135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer negó ... algo en la orilla lejana.'::text,'haber visto'::text,'haber visto'::text,'ver'::text,'Oye, al parecer negó haber visto algo en la orilla lejana.'::text),
(352211,39135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle a nié ... quoi que ce soit sur la rive lointaine.'::text,'avoir vu'::text,'avoir vu'::text,'voir'::text,'Écoute, apparemment elle a nié avoir vu quoi que ce soit sur la rive lointaine.'::text),
(352214,39135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan uzak kıyıda bir şey ... inkâr etmiş.'::text,'gördüğünü'::text,'görmüş olduğunu'::text,'görmeyi'::text,'Dinle, anlaşılan uzak kıyıda bir şey gördüğünü inkâr etmiş.'::text),
(352215,39135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag tagadta, hogy bármit ... a távoli parton.'::text,'látott volna'::text,'látott volna'::text,'lát'::text,'Figyelj, állítólag tagadta, hogy bármit látott volna a távoli parton.'::text),
(352218,39136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, die Klippen waren so weit weg, dass sie durch dieses Fernglas nicht viel gesehen ...'::text,'haben kann'::text,'haben muss'::text,'haben sollte'::text,'Bestie, ich hab gehört, die Klippen waren so weit weg, dass sie durch dieses Fernglas nicht viel gesehen haben kann.'::text),
(352222,39136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула, що скелі були так далеко, що вона ... багато побачити в той бінокль.'::text,'не могла'::text,'мусила'::text,'не мала'::text,'Подружко, я чула, що скелі були так далеко, що вона не могла багато побачити в той бінокль.'::text),
(352221,39136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijeron que los acantilados estaban tan lejos que ... visto mucho con esos prismáticos.'::text,'no puede haber'::text,'debe de haber'::text,'no debería haber'::text,'Amiga, me dijeron que los acantilados estaban tan lejos que no puede haber visto mucho con esos prismáticos.'::text),
(352220,39136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu que les falaises étaient si loin qu''elle ... vu grand-chose avec ces jumelles.'::text,'n''a pas pu'::text,'a dû'::text,'n''aurait pas dû'::text,'Meuf, j''ai entendu que les falaises étaient si loin qu''elle n''a pas pu vu grand-chose avec ces jumelles.'::text),
(352223,39136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki kayalıklar o kadar uzakmış ki o dürbünle pek bir şey ...'::text,'görmüş olamaz'::text,'görmüş olmalı'::text,'görmemeliydi'::text,'Kanka, duydum ki kayalıklar o kadar uzakmış ki o dürbünle pek bir şey görmüş olamaz.'::text),
(352224,39136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a sziklák olyan messze voltak, hogy azzal a távcsővel ... sokat.'::text,'nem láthatott'::text,'biztos látott'::text,'nem kellett volna látnia'::text,'Csajszi, azt hallottam, hogy a sziklák olyan messze voltak, hogy azzal a távcsővel nem láthatott sokat.'::text),
(352236,39138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie wünscht sich, die Klippen ... nicht so weit weg, ohne Witz.'::text,'wären'::text,'sind'::text,'werden sein'::text,'Bro, sie wünscht sich, die Klippen wären nicht so weit weg, ohne Witz.'::text),
(352240,39138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона хоче, щоб скелі ... так далеко, без жартів.'::text,'не були'::text,'не є'::text,'не будуть'::text,'Бро, вона хоче, щоб скелі не були так далеко, без жартів.'::text),
(352239,39138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella desearía que los acantilados no ... tan lejos, en serio.'::text,'estuvieran'::text,'están'::text,'estarán'::text,'Bro, ella desearía que los acantilados no estuvieran tan lejos, en serio.'::text),
(352238,39138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle aimerait que les falaises ne ... pas si loin, sans mentir.'::text,'soient'::text,'sont'::text,'seront'::text,'Frère, elle aimerait que les falaises ne soient pas si loin, sans mentir.'::text),
(352241,39138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke kayalıklar bu kadar uzak ... diyor, yalan yok.'::text,'olmasa'::text,'değil'::text,'olmayacak'::text,'Kanka, keşke kayalıklar bu kadar uzak olmasa diyor, yalan yok.'::text),
(352242,39138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt szeretné, ha a sziklák ne ... ilyen messze, komolyan.'::text,'lennének'::text,'vannak'::text,'lesznek'::text,'Tesó, azt szeretné, ha a sziklák ne lennének ilyen messze, komolyan.'::text),
(352245,39139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Turmfernrohr, ... 2 Euro pro Minute kostet, ist eine solide Investition in weite Ausblicke.'::text,'das'::text,'dessen'::text,'wer'::text,'Das Turmfernrohr, das 2 Euro pro Minute kostet, ist eine solide Investition in weite Ausblicke.'::text),
(352249,39139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оглядовий бінокль, ... коштує 2 євро за хвилину, – це надійна інвестиція в далекі краєвиди.'::text,'який'::text,'чий'::text,'хто'::text,'Оглядовий бінокль, який коштує 2 євро за хвилину, – це надійна інвестиція в далекі краєвиди.'::text),
(352248,39139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El telescopio del mirador, ... cuesta 2 euros por minuto, es una inversión sólida en vistas lejanas.'::text,'que'::text,'cuyo'::text,'quien'::text,'El telescopio del mirador, que cuesta 2 euros por minuto, es una inversión sólida en vistas lejanas.'::text),
(352247,39139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La longue-vue du belvédère, ... coûte 2 euros la minute, est un investissement solide pour les vues lointaines.'::text,'qui'::text,'dont'::text,'qui'::text,'La longue-vue du belvédère, qui coûte 2 euros la minute, est un investissement solide pour les vues lointaines.'::text),
(352250,39139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kule dürbünü, ... dakikası 2 euro tutuyor, uzak manzaralar için sağlam bir yatırım.'::text,'ki'::text,'ki'::text,'kim'::text,'Kule dürbünü, ki dakikası 2 euro tutuyor, uzak manzaralar için sağlam bir yatırım.'::text),
(352251,39139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kilátótorony távcsöve, ... percenként 2 euróba kerül, szilárd befektetés a távoli kilátásokért.'::text,'amely'::text,'amelynek'::text,'aki'::text,'A kilátótorony távcsöve, amely percenként 2 euróba kerül, szilárd befektetés a távoli kilátásokért.'::text),
(352254,39140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie benutzte ein Turmfernrohr, ... die Klippen für ihr Fernglas zu weit weg waren.'::text,'weil'::text,'wegen'::text,'trotz'::text,'Sie benutzte ein Turmfernrohr, weil die Klippen für ihr Fernglas zu weit weg waren.'::text),
(352258,39140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона скористалася оглядовим біноклем, ... скелі були надто далеко для її бінокля.'::text,'бо'::text,'через'::text,'попри'::text,'Вона скористалася оглядовим біноклем, бо скелі були надто далеко для її бінокля.'::text),
(352257,39140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Usó el telescopio del mirador ... los acantilados estaban demasiado lejos para sus prismáticos.'::text,'porque'::text,'debido a'::text,'a pesar de'::text,'Usó el telescopio del mirador porque los acantilados estaban demasiado lejos para sus prismáticos.'::text),
(352256,39140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a utilisé une longue-vue ... les falaises étaient trop loin pour ses jumelles.'::text,'parce que'::text,'à cause de'::text,'malgré'::text,'Elle a utilisé une longue-vue parce que les falaises étaient trop loin pour ses jumelles.'::text),
(352259,39140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayalıklar dürbünü için çok uzak olduğu ... kule dürbününü kullandı.'::text,'için'::text,'yüzünden'::text,'rağmen'::text,'Kayalıklar dürbünü için çok uzak olduğu için kule dürbününü kullandı.'::text),
(352260,39140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toronytávcsövet használt, ... a sziklák túl messze voltak a távcsövéhez.'::text,'mert'::text,'miatt'::text,'ellenére'::text,'Toronytávcsövet használt, mert a sziklák túl messze voltak a távcsövéhez.'::text),
(352263,39141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis morgen Abend wird sie zwei Tage lang ferne Ufer mit dem Fernglas ...'::text,'abgesucht haben'::text,'absuchen'::text,'absuchen'::text,'Bis morgen Abend wird sie zwei Tage lang ferne Ufer mit dem Fernglas abgesucht haben.'::text),
(352267,39141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До завтрашнього вечора вона вже два дні ... далекі береги в бінокль.'::text,'розглядатиме'::text,'розглядатиме'::text,'розгляне'::text,'До завтрашнього вечора вона вже два дні розглядатиме далекі береги в бінокль.'::text),
(352266,39141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana por la noche ya ... las orillas lejanas con prismáticos durante dos días.'::text,'habrá estado escudriñando'::text,'estará escudriñando'::text,'escudriñará'::text,'Mañana por la noche ya habrá estado escudriñando las orillas lejanas con prismáticos durante dos días.'::text),
(352265,39141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici demain soir, elle ... les rives lointaines aux jumelles pendant deux jours.'::text,'aura scruté'::text,'sera en train de scruter'::text,'scrutera'::text,'D''ici demain soir, elle aura scruté les rives lointaines aux jumelles pendant deux jours.'::text),
(352268,39141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın akşama kadar iki gündür uzak kıyıları dürbünle ...'::text,'taramış olacak'::text,'tarıyor olacak'::text,'tarayacak'::text,'Yarın akşama kadar iki gündür uzak kıyıları dürbünle taramış olacak.'::text),
(352269,39141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap estére már két napja ... a távoli partokat távcsővel.'::text,'pásztázza majd'::text,'fogja pásztázni'::text,'pásztázza'::text,'Holnap estére már két napja pásztázza majd a távoli partokat távcsővel.'::text),
(330636,36738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit dem Mittagessen, und sein Appetit ist immer noch riesig.'::text,'isst'::text,'isst'::text,'isst'::text,'Er isst seit dem Mittagessen, und sein Appetit ist immer noch riesig.'::text),
(330640,36738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... з обіду, а апетит у нього досі величезний.'::text,'їсть'::text,'їсть'::text,'їсть'::text,'Він їсть з обіду, а апетит у нього досі величезний.'::text),
(330639,36738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... desde el almuerzo y su apetito sigue siendo enorme.'::text,'Ha estado comiendo'::text,'Está comiendo'::text,'Come'::text,'Ha estado comiendo desde el almuerzo y su apetito sigue siendo enorme.'::text),
(330638,36738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... depuis le déjeuner, et son appétit est toujours énorme.'::text,'mange'::text,'mange'::text,'mange'::text,'Il mange depuis le déjeuner, et son appétit est toujours énorme.'::text),
(330641,36738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğinden beri ... ve iştahı hâlâ çok büyük.'::text,'yiyor'::text,'yiyor'::text,'yer'::text,'Öğle yemeğinden beri yiyor ve iştahı hâlâ çok büyük.'::text),
(330642,36738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebéd óta ..., és még mindig óriási az étvágya.'::text,'eszik'::text,'eszik'::text,'eszik'::text,'Ebéd óta eszik, és még mindig óriási az étvágya.'::text),
(330654,36740,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat bisher vier riesige Burger ... Ein winziger Appetit, ganz klar.'::text,'gegessen'::text,'gegessen'::text,'isst'::text,'Er hat bisher vier riesige Burger gegessen Ein winziger Appetit, ganz klar.'::text),
(330658,36740,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... чотири величезні бургери. Крихітний апетит, очевидно.'::text,'з''їв'::text,'їв'::text,'їсть'::text,'Він уже з''їв чотири величезні бургери. Крихітний апетит, очевидно.'::text),
(330657,36740,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... cuatro hamburguesas enormes. Un apetito diminuto, obviamente.'::text,'se ha comido'::text,'ha estado comiendo'::text,'está comiendo'::text,'Hasta ahora se ha comido cuatro hamburguesas enormes. Un apetito diminuto, obviamente.'::text),
(330656,36740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... quatre burgers énormes jusqu''ici. Un tout petit appétit, évidemment.'::text,'a mangé'::text,'mange'::text,'mange'::text,'Il a mangé quatre burgers énormes jusqu''ici. Un tout petit appétit, évidemment.'::text),
(330659,36740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar dört dev burger ... bile. Minicik bir iştah, tabii.'::text,'yedi'::text,'yiyip durdu'::text,'yiyor'::text,'Şimdiye kadar dört dev burger yedi bile. Minicik bir iştah, tabii.'::text),
(330660,36740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ... négy óriási burgert. Pici étvágy, nyilván.'::text,'megevett'::text,'evett'::text,'eszik'::text,'Már megevett négy óriási burgert. Pici étvágy, nyilván.'::text),
(330663,36741,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Wassermelone kam, ... er schon einen ganzen Burger verputzt. Ein kleiner Appetit, ganz klar.'::text,'hatte'::text,'hat'::text,'verputzt'::text,'Als die Wassermelone kam, hatte er schon einen ganzen Burger verputzt. Ein kleiner Appetit, ganz klar.'::text),
(330667,36741,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли принесли кавун, він уже ... цілий бургер. Маленький апетит, очевидно.'::text,'доїв'::text,'доїв'::text,'доїдає'::text,'Коли принесли кавун, він уже доїв цілий бургер. Маленький апетит, очевидно.'::text),
(330666,36741,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegó la sandía, ya ... una hamburguesa entera. Un apetito pequeño, obviamente.'::text,'se había terminado'::text,'se ha terminado'::text,'se termina'::text,'Cuando llegó la sandía, ya se había terminado una hamburguesa entera. Un apetito pequeño, obviamente.'::text),
(330665,36741,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la pastèque est arrivée, il ... un burger entier. Un petit appétit, évidemment.'::text,'avait fini'::text,'a fini'::text,'finit'::text,'Quand la pastèque est arrivée, il avait fini un burger entier. Un petit appétit, évidemment.'::text),
(330668,36741,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karpuz geldiğinde koca bir burgeri ... bile. Küçük bir iştah, tabii.'::text,'bitirmişti'::text,'bitirdi'::text,'bitiriyor'::text,'Karpuz geldiğinde koca bir burgeri bitirmişti bile. Küçük bir iştah, tabii.'::text),
(330669,36741,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megjött a görögdinnye, már ... egy egész burgert. Kis étvágy, nyilván.'::text,'megette'::text,'megette'::text,'megeszi'::text,'Mire megjött a görögdinnye, már megette egy egész burgert. Kis étvágy, nyilván.'::text),
(330672,36742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn er so weiter Appetit hat, ... nichts mehr zu essen übrig, echt jetzt.'::text,'gibt es'::text,'gäbe es'::text,'gab es'::text,'Bro, wenn er so weiter Appetit hat, gibt es nichts mehr zu essen übrig, echt jetzt.'::text),
(330676,36742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо в нього й далі буде такий апетит, ... ніякої їжі, чесно.'::text,'не залишиться'::text,'не залишилося б'::text,'не залишилося'::text,'Бро, якщо в нього й далі буде такий апетит, не залишиться ніякої їжі, чесно.'::text),
(330675,36742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si sigue con ese apetito, no ... nada de comida, en serio.'::text,'quedará'::text,'quedaría'::text,'quedaba'::text,'Bro, si sigue con ese apetito, no quedará nada de comida, en serio.'::text),
(330674,36742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, s''il garde cet appétit, il ... plus rien à manger, sérieux.'::text,'ne restera'::text,'ne resterait'::text,'ne restait'::text,'Frère, s''il garde cet appétit, il ne restera plus rien à manger, sérieux.'::text),
(330677,36742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu iştahla devam ederse hiç yemek ..., cidden.'::text,'kalmayacak'::text,'kalmazdı'::text,'kalmadı'::text,'Kanka, bu iştahla devam ederse hiç yemek kalmayacak, cidden.'::text),
(330678,36742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha ilyen marad az étvágya, nem ... semmi kaja, komolyan.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Tesó, ha ilyen marad az étvágya, nem marad semmi kaja, komolyan.'::text),
(330681,36743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn ich seinen Appetit hätte, ... ich auch den ganzen Burger essen, ohne Witz.'::text,'würde'::text,'werde'::text,'esse'::text,'Alter, wenn ich seinen Appetit hätte, würde ich auch den ganzen Burger essen, ohne Witz.'::text),
(330685,36743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби в мене був його апетит, я теж ... цей цілий бургер, без жартів.'::text,'з''їв би'::text,'з''їм'::text,'їм'::text,'Чувак, якби в мене був його апетит, я теж з''їв би цей цілий бургер, без жартів.'::text),
(330684,36743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si tuviera su apetito, yo también ... esa hamburguesa entera, en serio.'::text,'me comería'::text,'me comeré'::text,'me como'::text,'Tío, si tuviera su apetito, yo también me comería esa hamburguesa entera, en serio.'::text),
(330683,36743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si j''avais son appétit, je ... ce burger entier moi aussi, sans mentir.'::text,'mangerais'::text,'mangerai'::text,'mange'::text,'Mec, si j''avais son appétit, je mangerais ce burger entier moi aussi, sans mentir.'::text),
(330686,36743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun iştahı bende olsa, o koca burgeri ben de ..., yalan yok.'::text,'yerdim'::text,'yiyeceğim'::text,'yiyorum'::text,'Kanka, onun iştahı bende olsa, o koca burgeri ben de yerdim, yalan yok.'::text),
(330687,36743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha nekem lenne ilyen étvágyam, én is ... azt az egész burgert, komolyan.'::text,'megenném'::text,'megeszem'::text,'eszem'::text,'Haver, ha nekem lenne ilyen étvágyam, én is megenném azt az egész burgert, komolyan.'::text),
(330690,36744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Für das Picknick ... Essen für 6 Personen bestellt, aber sein Appetit hat das Budget gesprengt.'::text,'wurde'::text,'bestellte'::text,'wird'::text,'Für das Picknick wurde Essen für 6 Personen bestellt, aber sein Appetit hat das Budget gesprengt.'::text),
(330694,36744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Для пікніка ... їжу на 6 осіб, але його апетит розніс бюджет.'::text,'було замовлено'::text,'замовили'::text,'замовляється'::text,'Для пікніка було замовлено їжу на 6 осіб, але його апетит розніс бюджет.'::text),
(330693,36744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comida para 6 personas ... para el pícnic, pero su apetito reventó el presupuesto.'::text,'fue encargada'::text,'encargó'::text,'es encargada'::text,'La comida para 6 personas fue encargada para el pícnic, pero su apetito reventó el presupuesto.'::text),
(330692,36744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De la nourriture pour 6 personnes ... pour le pique-nique, mais son appétit a explosé le budget.'::text,'a été commandée'::text,'a commandé'::text,'est commandée'::text,'De la nourriture pour 6 personnes a été commandée pour le pique-nique, mais son appétit a explosé le budget.'::text),
(330695,36744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piknik için 6 kişilik yemek ..., ama onun iştahı bütçeyi patlattı.'::text,'sipariş edildi'::text,'sipariş etti'::text,'sipariş ediliyor'::text,'Piknik için 6 kişilik yemek sipariş edildi, ama onun iştahı bütçeyi patlattı.'::text),
(330696,36744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piknikre 6 főre ... ételt, de az étvágya szétrobbantotta a költségvetést.'::text,'rendeltek'::text,'rendelt'::text,'rendelnek'::text,'A piknikre 6 főre rendeltek ételt, de az étvágya szétrobbantotta a költségvetést.'::text),
(330699,36745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er isst schon die dritte Mahlzeit, also ... sein Appetit heute echt groß sein.'::text,'muss'::text,'kann nicht'::text,'könnte nicht'::text,'Er isst schon die dritte Mahlzeit, also muss sein Appetit heute echt groß sein.'::text),
(330703,36745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він їсть уже втретє, тож його апетит сьогодні ... бути дуже великим.'::text,'має'::text,'не може'::text,'може не'::text,'Він їсть уже втретє, тож його апетит сьогодні має бути дуже великим.'::text),
(330702,36745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ya va por la tercera comida, así que su apetito ... ser enorme hoy.'::text,'debe de'::text,'no puede'::text,'puede que no'::text,'Ya va por la tercera comida, así que su apetito debe de ser enorme hoy.'::text),
(330701,36745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il en est à son troisième repas, donc son appétit ... être énorme aujourd''hui.'::text,'doit'::text,'ne peut pas'::text,'pourrait ne pas'::text,'Il en est à son troisième repas, donc son appétit doit être énorme aujourd''hui.'::text),
(330704,36745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üçüncü öğününü yiyor, yani bugün iştahı çok büyük ...'::text,'olmalı'::text,'olamaz'::text,'olmayabilir'::text,'Üçüncü öğününü yiyor, yani bugün iştahı çok büyük olmalı.'::text),
(330705,36745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már a harmadik adagot eszi, szóval ma ... nagyon nagy az étvágya.'::text,'biztosan'::text,'nem lehet'::text,'talán nem'::text,'Már a harmadik adagot eszi, szóval ma biztosan nagyon nagy az étvágya.'::text),
(330708,36746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das junge Männchen, ... Appetit bemerkenswert erscheint, verzehrt einen Burger und eine Wassermelone.'::text,'dessen'::text,'das'::text,'welches'::text,'Das junge Männchen, dessen Appetit bemerkenswert erscheint, verzehrt einen Burger und eine Wassermelone.'::text),
(330712,36746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий самець, ... апетит видається видатним, споживає бургер і кавун.'::text,'чий'::text,'який'::text,'котрий'::text,'Молодий самець, чий апетит видається видатним, споживає бургер і кавун.'::text),
(330711,36746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven macho, ... apetito parece notable, consume una hamburguesa y una sandía.'::text,'cuyo'::text,'quien'::text,'el cual'::text,'El joven macho, cuyo apetito parece notable, consume una hamburguesa y una sandía.'::text),
(330710,36746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune mâle, ... l''appétit semble remarquable, consomme un burger et une pastèque.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le jeune mâle, dont l''appétit semble remarquable, consomme un burger et une pastèque.'::text),
(330713,36746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç erkek, ... iştahı dikkat çekici görünüyor, bir burger ve bir karpuz tüketiyor.'::text,'ki'::text,'ki'::text,'ki'::text,'Genç erkek, ki iştahı dikkat çekici görünüyor, bir burger ve bir karpuz tüketiyor.'::text),
(330714,36746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal hím, ... étvágya figyelemre méltónak tűnik, elfogyaszt egy burgert és egy görögdinnyét.'::text,'akinek'::text,'aki'::text,'amely'::text,'A fiatal hím, akinek étvágya figyelemre méltónak tűnik, elfogyaszt egy burgert és egy görögdinnyét.'::text),
(330717,36747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er erzählte seinen Freunden, dass sein Appetit noch nie so groß ...'::text,'gewesen war'::text,'gewesen ist'::text,'ist'::text,'Er erzählte seinen Freunden, dass sein Appetit noch nie so groß gewesen war.'::text),
(330721,36747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він розповів друзям, що його апетит ще ... таким великим.'::text,'ніколи не був'::text,'ніколи не був'::text,'ніколи не є'::text,'Він розповів друзям, що його апетит ще ніколи не був таким великим.'::text),
(330720,36747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les dijo a sus amigos que su apetito nunca ... tan grande.'::text,'había sido'::text,'ha sido'::text,'es'::text,'Les dijo a sus amigos que su apetito nunca había sido tan grande.'::text),
(330719,36747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit à ses potes que son appétit ... aussi énorme.'::text,'n''avait jamais été'::text,'n''a jamais été'::text,'n''est jamais'::text,'Il a dit à ses potes que son appétit n''avait jamais été aussi énorme.'::text),
(330722,36747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlarına iştahının daha önce hiç bu kadar büyük ... söyledi.'::text,'olmadığını'::text,'olmadığını'::text,'olmadığını'::text,'Arkadaşlarına iştahının daha önce hiç bu kadar büyük olmadığını söyledi.'::text),
(330723,36747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a barátainak, hogy az étvágya még ... ilyen nagy.'::text,'soha nem volt'::text,'soha nem volt'::text,'soha nincs'::text,'Azt mondta a barátainak, hogy az étvágya még soha nem volt ilyen nagy.'::text),
(364809,40535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, er hat zugegeben, dass er gerade noch eine Schicht Decken ..., als ich ihn angerufen hab.'::text,'draufpackte'::text,'draufpackte'::text,'draufgepackt hat'::text,'Rate mal, er hat zugegeben, dass er gerade noch eine Schicht Decken draufpackte, als ich ihn angerufen hab.'::text),
(364813,40535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, він зізнався, що ... ще один шар ковдр, коли я йому подзвонила.'::text,'додавав'::text,'додав'::text,'додав'::text,'Уяви, він зізнався, що додавав ще один шар ковдр, коли я йому подзвонила.'::text),
(364812,40535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, admitió que ... otra capa de mantas cuando lo llamé.'::text,'estaba añadiendo'::text,'añadió'::text,'ha añadido'::text,'Adivina qué, admitió que estaba añadiendo otra capa de mantas cuando lo llamé.'::text),
(364811,40535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il a avoué qu''il ... une autre couche de couvertures quand je l''ai appelé.'::text,'était en train d''ajouter'::text,'a ajouté'::text,'a ajouté'::text,'Devine quoi, il a avoué qu''il était en train d''ajouter une autre couche de couvertures quand je l''ai appelé.'::text),
(364814,40535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, onu aradığımda bir kat battaniye daha ... itiraf etti.'::text,'ekliyor olduğunu'::text,'eklediğini'::text,'eklemiş olduğunu'::text,'Tahmin et ne oldu, onu aradığımda bir kat battaniye daha ekliyor olduğunu itiraf etti.'::text),
(364815,40535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, bevallotta, hogy ... még egy réteg takarót, amikor felhívtam.'::text,'épp terített magára'::text,'terített magára'::text,'terített magára'::text,'Képzeld, bevallotta, hogy épp terített magára még egy réteg takarót, amikor felhívtam.'::text),
(364818,40536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... er den ganzen Vormittag Decken in Schichten.'::text,'stapelt'::text,'stapelt'::text,'stapelt'::text,'Bestie, angeblich stapelt er den ganzen Vormittag Decken in Schichten.'::text),
(364822,40536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, він увесь ранок ... ковдри шарами.'::text,'накладає'::text,'накладає'::text,'накладає'::text,'Подружко, кажуть, він увесь ранок накладає ковдри шарами.'::text),
(364821,40536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... mantas en capas toda la mañana.'::text,'ha estado apilando'::text,'está apilando'::text,'apila'::text,'Amiga, al parecer ha estado apilando mantas en capas toda la mañana.'::text),
(364820,40536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... des couvertures en couches toute la matinée.'::text,'empile'::text,'empile'::text,'empile'::text,'Meuf, apparemment il empile des couvertures en couches toute la matinée.'::text),
(364823,40536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan bütün sabah battaniyeleri kat kat ...'::text,'yığıyormuş'::text,'yığıyor'::text,'yığar'::text,'Kanka, anlaşılan bütün sabah battaniyeleri kat kat yığıyormuş.'::text),
(364824,40536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egész délelőtt ... rétegekben a takarókat.'::text,'halmozza'::text,'halmozza'::text,'halmozza'::text,'Csajszi, állítólag egész délelőtt halmozza rétegekben a takarókat.'::text),
(364827,40537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... gerade die dritte Schicht drüber, als er anfing zu grinsen, ohne Witz.'::text,'zog'::text,'zog'::text,'hat gezogen'::text,'Bro, er zog gerade die dritte Schicht drüber, als er anfing zu grinsen, ohne Witz.'::text),
(364831,40537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... на себе третій шар, коли почав шкіритися, без жартів.'::text,'натягував'::text,'натягнув'::text,'натягнув'::text,'Бро, він натягував на себе третій шар, коли почав шкіритися, без жартів.'::text),
(364830,40537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... la tercera capa encima cuando empezó a sonreír, en serio.'::text,'estaba poniéndose'::text,'se puso'::text,'se ha puesto'::text,'Bro, estaba poniéndose la tercera capa encima cuando empezó a sonreír, en serio.'::text),
(364829,40537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... la troisième couche quand il a commencé à sourire, sans mentir.'::text,'était en train de remonter'::text,'a remonté'::text,'a remonté'::text,'Frère, il était en train de remonter la troisième couche quand il a commencé à sourire, sans mentir.'::text),
(364832,40537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sırıtmaya başladığında üçüncü katı üstüne ..., yalan yok.'::text,'çekiyordu'::text,'çekti'::text,'çekmiş'::text,'Kanka, sırıtmaya başladığında üçüncü katı üstüne çekiyordu, yalan yok.'::text),
(364833,40537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... magára a harmadik réteget, amikor vigyorogni kezdett, komolyan.'::text,'húzta'::text,'húzta'::text,'húzta'::text,'Tesó, épp húzta magára a harmadik réteget, amikor vigyorogni kezdett, komolyan.'::text),
(364836,40538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er hat schon so fünf Schichten Decken ..., ohne Witz.'::text,'draufgepackt'::text,'draufgepackt'::text,'draufgepackt'::text,'Bro, er hat schon so fünf Schichten Decken draufgepackt, ohne Witz.'::text),
(364840,40538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він уже ... на себе десь п''ять шарів ковдр, без жартів.'::text,'натягнув'::text,'натягував'::text,'натягнув'::text,'Бро, він уже натягнув на себе десь п''ять шарів ковдр, без жартів.'::text),
(364839,40538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ya ... como cinco capas de mantas, en serio.'::text,'se ha puesto'::text,'se ha estado poniendo'::text,'se puso'::text,'Bro, ya se ha puesto como cinco capas de mantas, en serio.'::text),
(364838,40538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... déjà genre cinq couches de couvertures, sans mentir.'::text,'a mis'::text,'met'::text,'a mis'::text,'Frère, il a mis déjà genre cinq couches de couvertures, sans mentir.'::text),
(364841,40538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şimdiden beş kat battaniye falan ..., yalan yok.'::text,'örtünmüş'::text,'örtünüyor'::text,'örtündü'::text,'Kanka, şimdiden beş kat battaniye falan örtünmüş, yalan yok.'::text),
(364842,40538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már vagy öt réteg takarót ... magára, komolyan.'::text,'tett'::text,'rakott'::text,'tett'::text,'Tesó, már vagy öt réteg takarót tett magára, komolyan.'::text),
(364854,40540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch eine Schicht draufpackt, ... er unter mehr Decken, weil Schichten Decken sind.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn er noch eine Schicht draufpackt, ist er unter mehr Decken, weil Schichten Decken sind.'::text),
(364858,40540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він додасть ще один шар, він ... під більшою кількістю ковдр, бо шари – це ковдри.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо він додасть ще один шар, він буде під більшою кількістю ковдр, бо шари – це ковдри.'::text),
(364857,40540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si añade otra capa, ... bajo más mantas, porque las capas son mantas.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si añade otra capa, estará bajo más mantas, porque las capas son mantas.'::text),
(364856,40540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ajoute une autre couche, il ... sous plus de couvertures, parce que les couches, c''est des couvertures.'::text,'sera'::text,'serait'::text,'était'::text,'S''il ajoute une autre couche, il sera sous plus de couvertures, parce que les couches, c''est des couvertures.'::text),
(364859,40540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kat daha eklerse daha çok battaniyenin altında ..., çünkü katlar battaniyedir.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Bir kat daha eklerse daha çok battaniyenin altında olacak, çünkü katlar battaniyedir.'::text),
(364860,40540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy réteget rak magára, több takaró alatt ..., mert a rétegek takarók.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha még egy réteget rak magára, több takaró alatt lesz, mert a rétegek takarók.'::text),
(364863,40541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Subjekt eine Schicht entfernte, ... ihm erheblich kühler.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn das Subjekt eine Schicht entfernte, wäre ihm erheblich kühler.'::text),
(364867,40541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби суб''єкт зняв один шар, він ... значно прохолодніше.'::text,'почувався б'::text,'почуватиметься'::text,'почувається'::text,'Якби суб''єкт зняв один шар, він почувався б значно прохолодніше.'::text),
(364866,40541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el sujeto se quitara una capa, ... considerablemente más fresco.'::text,'se sentiría'::text,'se sentirá'::text,'se siente'::text,'Si el sujeto se quitara una capa, se sentiría considerablemente más fresco.'::text),
(364865,40541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sujet retirait une couche, il ... nettement plus au frais.'::text,'se sentirait'::text,'se sentira'::text,'se sent'::text,'Si le sujet retirait une couche, il se sentirait nettement plus au frais.'::text),
(364868,40541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek bir katı çıkarsa, kendini kayda değer ölçüde daha serin ...'::text,'hissederdi'::text,'hissedecek'::text,'hissediyor'::text,'Denek bir katı çıkarsa, kendini kayda değer ölçüde daha serin hissederdi.'::text),
(364869,40541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az alany levenne egy réteget, jelentősen hűvösebbnek ... magát.'::text,'érezné'::text,'fogja érezni'::text,'érzi'::text,'Ha az alany levenne egy réteget, jelentősen hűvösebbnek érezné magát.'::text),
(364872,40542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber du wusstest, dass eine Schicht nicht ..., und dieser Deckenberg ist ikonisch.'::text,'reichen würde'::text,'reichen wird'::text,'reicht'::text,'Okay, aber du wusstest, dass eine Schicht nicht reichen würde, und dieser Deckenberg ist ikonisch.'::text),
(364876,40542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але ти знав, що одного шару ..., і ця купа ковдр – культова.'::text,'не вистачить'::text,'не вистачить'::text,'не вистачає'::text,'Окей, але ти знав, що одного шару не вистачить, і ця купа ковдр – культова.'::text),
(364875,40542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero sabías que una capa no ..., y esa montaña de mantas es icónica.'::text,'sería suficiente'::text,'será suficiente'::text,'es suficiente'::text,'Vale, pero sabías que una capa no sería suficiente, y esa montaña de mantas es icónica.'::text),
(364874,40542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, mais tu savais qu''une couche ne ... pas, et cette pile de couvertures est iconique.'::text,'suffirait'::text,'suffira'::text,'suffit'::text,'Ok, mais tu savais qu''une couche ne suffirait pas, et cette pile de couvertures est iconique.'::text),
(364877,40542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam da bir katın ... biliyordun ve o battaniye yığını efsane.'::text,'yetmeyeceğini'::text,'yetmeyeceğini'::text,'yetmediğini'::text,'Tamam da bir katın yetmeyeceğini biliyordun ve o battaniye yığını efsane.'::text),
(364878,40542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de tudtad, hogy egy réteg nem ... elég, és az a takarókupac ikonikus.'::text,'lesz'::text,'lesz'::text,NULL::text,'Oké, de tudtad, hogy egy réteg nem lesz elég, és az a takarókupac ikonikus.'::text),
(364890,40544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihm ... eine Weile kalt, bevor er die erste Schicht draufpackte.'::text,'war'::text,'ist'::text,'ist'::text,'Ihm war eine Weile kalt, bevor er die erste Schicht draufpackte.'::text),
(364894,40544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому якийсь час ... холодно, перш ніж він додав перший шар.'::text,'було'::text,'є'::text,'є'::text,'Йому якийсь час було холодно, перш ніж він додав перший шар.'::text),
(364893,40544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... frío un buen rato antes de ponerse la primera capa.'::text,'Había estado pasando'::text,'Ha estado pasando'::text,'Pasa'::text,'Había estado pasando frío un buen rato antes de ponerse la primera capa.'::text),
(364892,40544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... froid depuis un moment avant d''ajouter la première couche.'::text,'avait'::text,'a'::text,'a'::text,'Il avait froid depuis un moment avant d''ajouter la première couche.'::text),
(364895,40544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk katı eklemeden önce bir süredir ...'::text,'üşüyordu'::text,'üşüyor'::text,'üşür'::text,'İlk katı eklemeden önce bir süredir üşüyordu.'::text),
(364896,40544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy ideje ..., mielőtt magára rakta az első réteget.'::text,'fázott'::text,'fázik'::text,'fázik'::text,'Egy ideje fázott, mielőtt magára rakta az első réteget.'::text),
(364899,40545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bald ... er unter so vielen Schichten begraben, dass nur noch sein Gesicht rausschaut.'::text,'ist'::text,'ist'::text,'war'::text,'Bald ist er unter so vielen Schichten begraben, dass nur noch sein Gesicht rausschaut.'::text),
(364903,40545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скоро він ... під такою кількістю шарів, що видно буде лише його обличчя.'::text,'буде засипаний'::text,'засипаний'::text,'був засипаний'::text,'Скоро він буде засипаний під такою кількістю шарів, що видно буде лише його обличчя.'::text),
(364902,40545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pronto ... bajo tantas capas que solo se le verá la cara.'::text,'estará enterrado'::text,'está enterrado'::text,'estaba enterrado'::text,'Pronto estará enterrado bajo tantas capas que solo se le verá la cara.'::text),
(364901,40545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bientôt il ... sous tellement de couches qu''on ne verra plus que son visage.'::text,'sera enseveli'::text,'est enseveli'::text,'était enseveli'::text,'Bientôt il sera enseveli sous tellement de couches qu''on ne verra plus que son visage.'::text),
(364904,40545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yakında o kadar çok katın altına ... ki sadece yüzü görünecek.'::text,'gömülecek'::text,'gömülü'::text,'gömüldü'::text,'Yakında o kadar çok katın altına gömülecek ki sadece yüzü görünecek.'::text),
(364905,40545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamarosan annyi réteg alatt ..., hogy csak az arca látszik ki.'::text,'lesz eltemetve'::text,'van eltemetve'::text,'volt eltemetve'::text,'Hamarosan annyi réteg alatt lesz eltemetve, hogy csak az arca látszik ki.'::text),
(362127,40237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um diese Zeit ... er über seine Fingerverletzung, echt jetzt.'::text,'jammert'::text,'jammert'::text,'jammert'::text,'Bro, morgen um diese Zeit jammert er über seine Fingerverletzung, echt jetzt.'::text),
(362131,40237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра о цій порі він ... на травму пальця, чесно.'::text,'скаржитиметься'::text,'поскаржиться'::text,'скаржиться'::text,'Бро, завтра о цій порі він скаржитиметься на травму пальця, чесно.'::text),
(362130,40237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a esta hora ... de su herida en el dedo, en serio.'::text,'estará quejándose'::text,'se quejará'::text,'se queja'::text,'Bro, mañana a esta hora estará quejándose de su herida en el dedo, en serio.'::text),
(362129,40237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, demain à la même heure, il ... de sa blessure au doigt, sérieux.'::text,'sera en train de se plaindre'::text,'se plaindra'::text,'se plaint'::text,'Frère, demain à la même heure, il sera en train de se plaindre de sa blessure au doigt, sérieux.'::text),
(362132,40237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatlerde parmağındaki yaralanmadan ..., cidden.'::text,'şikâyet ediyor olacak'::text,'şikâyet edecek'::text,'şikâyet ediyor'::text,'Kanka, yarın bu saatlerde parmağındaki yaralanmadan şikâyet ediyor olacak, cidden.'::text),
(362133,40237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor az ujjsérülése miatt ..., komolyan.'::text,'fog panaszkodni'::text,'panaszkodik majd'::text,'panaszkodik'::text,'Tesó, holnap ilyenkor az ujjsérülése miatt fog panaszkodni, komolyan.'::text),
(362136,40238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, chill, ich ... ein Pflaster auf die Verletzung.'::text,'klebe'::text,'klebe'::text,'klebe'::text,'Nee Alter, chill, ich klebe ein Pflaster auf die Verletzung.'::text),
(362140,40238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ні, чувак, спокійно, я ... пластир на цю травму.'::text,'наклею'::text,'клеїтиму'::text,'клею'::text,'Та ні, чувак, спокійно, я наклею пластир на цю травму.'::text),
(362139,40238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, tío, tranqui, ... una tirita en esa herida.'::text,'pondré'::text,'estaré poniendo'::text,'pongo'::text,'Nah, tío, tranqui, pondré una tirita en esa herida.'::text),
(362138,40238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non mec, tranquille, je ... un pansement sur cette blessure.'::text,'vais mettre'::text,'serai en train de mettre'::text,'mets'::text,'Non mec, tranquille, je vais mettre un pansement sur cette blessure.'::text),
(362141,40238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, sakin, o yaraya bir bant ...'::text,'yapıştırırım'::text,'yapıştırıyor olacağım'::text,'yapıştırıyorum'::text,'Yok kanka, sakin, o yaraya bir bant yapıştırırım.'::text),
(362142,40238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, haver, nyugi, ... egy sebtapaszt arra a sérülésre.'::text,'rakok'::text,'fogok rakni'::text,'rakok'::text,'Nem, haver, nyugi, rakok egy sebtapaszt arra a sérülésre.'::text),
(362145,40239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verletzung ... in unter 60 Sekunden versorgt, gemäß Küchenprotokoll.'::text,'wurde'::text,'versorgte'::text,'versorgt'::text,'Die Verletzung wurde in unter 60 Sekunden versorgt, gemäß Küchenprotokoll.'::text),
(362149,40239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Травму ... менш ніж за 60 секунд, згідно з кухонним протоколом.'::text,'було оброблено'::text,'обробила'::text,'обробляє'::text,'Травму було оброблено менш ніж за 60 секунд, згідно з кухонним протоколом.'::text),
(362148,40239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La herida ... en menos de 60 segundos, según el protocolo de cocina.'::text,'fue tratada'::text,'trató'::text,'está tratando'::text,'La herida fue tratada en menos de 60 segundos, según el protocolo de cocina.'::text),
(362147,40239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La blessure ... en moins de 60 secondes, selon le protocole de cuisine.'::text,'a été soignée'::text,'a soigné'::text,'est en train de soigner'::text,'La blessure a été soignée en moins de 60 secondes, selon le protocole de cuisine.'::text),
(362150,40239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaralanma, mutfak protokolüne göre 60 saniyeden kısa sürede ...'::text,'tedavi edildi'::text,'tedavi etti'::text,'tedavi ediyor'::text,'Yaralanma, mutfak protokolüne göre 60 saniyeden kısa sürede tedavi edildi.'::text),
(362151,40239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sérülést a konyhai protokoll szerint 60 másodpercen belül ...'::text,'ellátták'::text,'ellátta'::text,'látja el'::text,'A sérülést a konyhai protokoll szerint 60 másodpercen belül ellátták.'::text),
(362154,40240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Verletzung ... durch das Messer verursacht, also war es das Messer.'::text,'wurde'::text,'verursachte'::text,'verursachend'::text,'Seine Verletzung wurde durch das Messer verursacht, also war es das Messer.'::text),
(362158,40240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його травму ... ножем, отже, це зробив ніж.'::text,'було завдано'::text,'завдала'::text,'завдаючи'::text,'Його травму було завдано ножем, отже, це зробив ніж.'::text),
(362157,40240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su herida ... por el cuchillo, así que fue el cuchillo.'::text,'fue causada'::text,'causó'::text,'causando'::text,'Su herida fue causada por el cuchillo, así que fue el cuchillo.'::text),
(362156,40240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa blessure ... par le couteau, donc c''est le couteau qui l''a faite.'::text,'a été causée'::text,'a causé'::text,'causant'::text,'Sa blessure a été causée par le couteau, donc c''est le couteau qui l''a faite.'::text),
(362159,40240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaralanması bıçak tarafından ..., yani bunu bıçak yaptı.'::text,'yapıldı'::text,'yaptı'::text,'yapan'::text,'Yaralanması bıçak tarafından yapıldı, yani bunu bıçak yaptı.'::text),
(362160,40240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sérülését a kés ..., szóval a kés volt.'::text,'okozta'::text,'okozta'::text,'okozva'::text,'A sérülését a kés okozta, szóval a kés volt.'::text),
(362163,40241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ein kleines Pflaster sie bedeckt, ... die Verletzung relativ geringfügig sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Da ein kleines Pflaster sie bedeckt, muss die Verletzung relativ geringfügig sein.'::text),
(362167,40241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оскільки її закриває маленький пластир, травма ... бути відносно незначною.'::text,'має'::text,'не може'::text,'не повинна'::text,'Оскільки її закриває маленький пластир, травма має бути відносно незначною.'::text),
(362166,40241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dado que la cubre una tirita pequeña, la herida ... ser relativamente leve.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Dado que la cubre una tirita pequeña, la herida debe de ser relativamente leve.'::text),
(362165,40241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Puisqu''un petit pansement la couvre, la blessure ... être relativement mineure.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Puisqu''un petit pansement la couvre, la blessure doit être relativement mineure.'::text),
(362168,40241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük bir yara bandı onu örttüğüne göre yaralanma nispeten hafif ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Küçük bir yara bandı onu örttüğüne göre yaralanma nispeten hafif olmalı.'::text),
(362169,40241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mivel egy kis sebtapasz fedi, a sérülés viszonylag enyhe ...'::text,'kell legyen'::text,'nem lehet'::text,'nem kéne legyen'::text,'Mivel egy kis sebtapasz fedi, a sérülés viszonylag enyhe kell legyen.'::text),
(362172,40242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Messer, ... seine Verletzung verursacht hat, ist absolut gnadenlos!'::text,'das'::text,'wer'::text,'dessen'::text,'Das Messer, das seine Verletzung verursacht hat, ist absolut gnadenlos!'::text),
(362176,40242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніж, ... завдав йому травми, абсолютно безжальний!'::text,'який'::text,'хто'::text,'чий'::text,'Ніж, який завдав йому травми, абсолютно безжальний!'::text),
(362175,40242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El cuchillo ... le causó la herida es absolutamente despiadado!'::text,'que'::text,'quien'::text,'cuyo'::text,'¡El cuchillo que le causó la herida es absolutamente despiadado!'::text),
(362174,40242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le couteau ... lui a causé cette blessure est absolument impitoyable !'::text,'qui'::text,'qui'::text,'dont'::text,'Le couteau qui lui a causé cette blessure est absolument impitoyable !'::text),
(362177,40242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bıçak, ... yaralanmasına sebep oldu, tamamen acımasız!'::text,'ki'::text,'ki'::text,'kimin'::text,'O bıçak, ki yaralanmasına sebep oldu, tamamen acımasız!'::text),
(362178,40242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kés, ... a sérülését okozta, teljesen kegyetlen!'::text,'amely'::text,'aki'::text,'akinek'::text,'A kés, amely a sérülését okozta, teljesen kegyetlen!'::text),
(362181,40243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, das Messer ... ihm eine schreckliche Verletzung zugefügt. Eine absolute Tragödie!'::text,'hatte'::text,'hat'::text,'fügt'::text,'Er schrie, das Messer hatte ihm eine schreckliche Verletzung zugefügt. Eine absolute Tragödie!'::text),
(362185,40243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що ніж ... йому жахливу травму. Справжня трагедія!'::text,'завдав'::text,'завдав'::text,'завдає'::text,'Він кричав, що ніж завдав йому жахливу травму. Справжня трагедія!'::text),
(362184,40243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gritó que el cuchillo le ... una herida terrible. ¡Una tragedia absoluta!'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'Gritó que el cuchillo le había hecho una herida terrible. ¡Una tragedia absoluta!'::text),
(362183,40243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hurlé que le couteau lui ... une blessure terrible. Tragédie absolue !'::text,'avait infligé'::text,'a infligé'::text,'inflige'::text,'Il a hurlé que le couteau lui avait infligé une blessure terrible. Tragédie absolue !'::text),
(362186,40243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bıçağın ona korkunç bir yara ... bağırdı. Tam bir trajedi!'::text,'açmış olduğunu'::text,'açtığını'::text,'açtığını'::text,'Bıçağın ona korkunç bir yara açmış olduğunu bağırdı. Tam bir trajedi!'::text),
(362187,40243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kiabálta, hogy a kés szörnyű sérülést ... neki. Igazi tragédia!'::text,'okozott'::text,'okozott'::text,'okoz'::text,'Azt kiabálta, hogy a kés szörnyű sérülést okozott neki. Igazi tragédia!'::text),
(362190,40244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... vorsichtig mit Messern, aber heute hat er sich eine Verletzung eingefangen.'::text,'war früher'::text,'wäre'::text,'war gewohnt'::text,'Er war früher vorsichtig mit Messern, aber heute hat er sich eine Verletzung eingefangen.'::text),
(362194,40244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... обережним із ножами, але сьогодні отримав травму.'::text,'раніше був'::text,'був би'::text,'звик бути'::text,'Він раніше був обережним із ножами, але сьогодні отримав травму.'::text),
(362193,40244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... tener cuidado con los cuchillos, pero hoy se hizo una herida.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Él solía tener cuidado con los cuchillos, pero hoy se hizo una herida.'::text),
(362192,40244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... prudent avec les couteaux, mais aujourd''hui il s''est fait une blessure.'::text,'était'::text,'serait'::text,'avait l''habitude d''être'::text,'Avant, il était prudent avec les couteaux, mais aujourd''hui il s''est fait une blessure.'::text),
(362195,40244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bıçaklarla eskiden dikkatli ..., ama bugün yaralandı.'::text,'davranırdı'::text,'davranırdı'::text,'davranmaya alışkındı'::text,'Bıçaklarla eskiden dikkatli davranırdı, ama bugün yaralandı.'::text),
(362196,40244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a késekkel, de ma megsérült.'::text,'óvatos volt'::text,'óvatos lett volna'::text,'hozzá volt szokva, hogy óvatos'::text,'Régen óvatos volt a késekkel, de ma megsérült.'::text),
(362208,40246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Finger ... nach der Verletzung, also hält er ihn unter den Wasserhahn.'::text,'blutet'::text,'blutet'::text,'hat geblutet'::text,'Sein Finger blutet nach der Verletzung, also hält er ihn unter den Wasserhahn.'::text),
(362212,40246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його палець ... після травми, тож він тримає його під краном.'::text,'кровить'::text,'кровить'::text,'кровив'::text,'Його палець кровить після травми, тож він тримає його під краном.'::text),
(362211,40246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su dedo ... tras la herida, así que lo pone bajo el grifo.'::text,'está sangrando'::text,'sangra'::text,'ha sangrado'::text,'Su dedo está sangrando tras la herida, así que lo pone bajo el grifo.'::text),
(362210,40246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son doigt ... après la blessure, alors il le passe sous le robinet.'::text,'saigne'::text,'saigne'::text,'a saigné'::text,'Son doigt saigne après la blessure, alors il le passe sous le robinet.'::text),
(362213,40246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaralanmadan sonra parmağı ..., bu yüzden onu musluğun altında tutuyor.'::text,'kanıyor'::text,'kanar'::text,'kanadı'::text,'Yaralanmadan sonra parmağı kanıyor, bu yüzden onu musluğun altında tutuyor.'::text),
(362214,40246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ujja ... a sérülés után, ezért a csap alá tartja.'::text,'vérzik'::text,'vérzik'::text,'vérzett'::text,'Az ujja vérzik a sérülés után, ezért a csap alá tartja.'::text),
(388758,43196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, ... die Visagistin beide Wangen geglättet und geht nun zur Stirn über.'::text,'hat'::text,'hat'::text,'glättete'::text,'Wie beobachtet, hat die Visagistin beide Wangen geglättet und geht nun zur Stirn über.'::text),
(388762,43196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як спостерігалося, візажистка ... обидві щоки і тепер переходить до чола.'::text,'розгладила'::text,'розгладжувала'::text,'розгладжувала'::text,'Як спостерігалося, візажистка розгладила обидві щоки і тепер переходить до чола.'::text),
(388761,43196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, la maquilladora ... ambas mejillas y ahora pasa a la frente.'::text,'ha alisado'::text,'ha estado alisando'::text,'estaba alisando'::text,'Según lo observado, la maquilladora ha alisado ambas mejillas y ahora pasa a la frente.'::text),
(388760,43196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, la maquilleuse ... les deux joues et passe maintenant au front.'::text,'a lissé'::text,'lisse'::text,'lissait'::text,'Comme observé, la maquilleuse a lissé les deux joues et passe maintenant au front.'::text),
(388763,43196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere, makyöz iki yanağı da ... ve şimdi alna geçiyor.'::text,'pürüzsüzleştirdi'::text,'pürüzsüzleştiriyordu'::text,'pürüzsüzleştiriyordu'::text,'Gözlemlendiği üzere, makyöz iki yanağı da pürüzsüzleştirdi ve şimdi alna geçiyor.'::text),
(388764,43196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy megfigyelhető, a sminkes ... mindkét arcot, és most a homlokra tér át.'::text,'elsimította'::text,'simította'::text,'simította'::text,'Ahogy megfigyelhető, a sminkes elsimította mindkét arcot, és most a homlokra tér át.'::text),
(388767,43197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie in den Spiegel sah, ... die Visagistin jede furchteinflößende Linie geglättet!'::text,'hatte'::text,'hat'::text,'glättet'::text,'Als sie in den Spiegel sah, hatte die Visagistin jede furchteinflößende Linie geglättet!'::text),
(388771,43197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона глянула в дзеркало, візажистка вже ... кожну жахливу лінію!'::text,'розгладила'::text,'розгладила'::text,'розгладжує'::text,'Коли вона глянула в дзеркало, візажистка вже розгладила кожну жахливу лінію!'::text),
(388770,43197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando se vio en el espejo, la maquilladora ya ... cada línea aterradora!'::text,'había alisado'::text,'ha alisado'::text,'alisa'::text,'¡Para cuando se vio en el espejo, la maquilladora ya había alisado cada línea aterradora!'::text),
(388769,43197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a vu le miroir, la maquilleuse ... chaque ligne terrifiante !'::text,'avait lissé'::text,'a lissé'::text,'lisse'::text,'Quand elle a vu le miroir, la maquilleuse avait lissé chaque ligne terrifiante !'::text),
(388772,43197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynaya baktığında makyöz her korkunç çizgiyi çoktan ...!'::text,'pürüzsüzleştirmişti'::text,'pürüzsüzleştirdi'::text,'pürüzsüzleştiriyor'::text,'Aynaya baktığında makyöz her korkunç çizgiyi çoktan pürüzsüzleştirmişti!'::text),
(388773,43197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a tükörbe nézett, a sminkes már ... minden ijesztő vonalat!'::text,'elsimította'::text,'elsimította'::text,'elsimítja'::text,'Mire a tükörbe nézett, a sminkes már elsimította minden ijesztő vonalat!'::text),
(388776,43198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede harte Linie ... in Sekunden weggeglättet und kommt nie wieder!'::text,'wurde'::text,'glättete'::text,'glättet'::text,'Jede harte Linie wurde in Sekunden weggeglättet und kommt nie wieder!'::text),
(388780,43198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожну різку лінію ... за лічені секунди, і вона вже ніколи не повернеться!'::text,'було розгладжено'::text,'розгладила'::text,'розгладжує'::text,'Кожну різку лінію було розгладжено за лічені секунди, і вона вже ніколи не повернеться!'::text),
(388779,43198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada línea dura ... en segundos, para no volver jamás!'::text,'fue alisada'::text,'alisó'::text,'está alisando'::text,'¡Cada línea dura fue alisada en segundos, para no volver jamás!'::text),
(388778,43198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque ligne dure ... en quelques secondes, pour ne jamais revenir !'::text,'a été lissée'::text,'a lissé'::text,'est en train de lisser'::text,'Chaque ligne dure a été lissée en quelques secondes, pour ne jamais revenir !'::text),
(388781,43198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her sert çizgi saniyeler içinde ..., bir daha asla dönmemek üzere!'::text,'pürüzsüzleştirildi'::text,'pürüzsüzleştirdi'::text,'pürüzsüzleştiriyor'::text,'Her sert çizgi saniyeler içinde pürüzsüzleştirildi, bir daha asla dönmemek üzere!'::text),
(388782,43198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden éles vonalat másodpercek alatt ..., hogy soha ne térjen vissza!'::text,'elsimítottak'::text,'elsimított'::text,'simít'::text,'Minden éles vonalat másodpercek alatt elsimítottak, hogy soha ne térjen vissza!'::text),
(388794,43200,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich schwör, die Visagistin ... ein Profi sein, sie hat die Linien so schnell geglättet.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Bestie, ich schwör, die Visagistin muss ein Profi sein, sie hat die Linien so schnell geglättet.'::text),
(388798,43200,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, клянуся, візажистка ... бути профі, вона так швидко розгладила ці лінії.'::text,'має'::text,'може'::text,'не може'::text,'Подружко, клянуся, візажистка має бути профі, вона так швидко розгладила ці лінії.'::text),
(388797,43200,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, te lo juro, la maquilladora ... ser una pro, alisó esas líneas rapidísimo.'::text,'tiene que'::text,'podría'::text,'no puede'::text,'Amiga, te lo juro, la maquilladora tiene que ser una pro, alisó esas líneas rapidísimo.'::text),
(388796,43200,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, je te jure, la maquilleuse ... être une pro, elle a lissé ces lignes trop vite.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Meuf, je te jure, la maquilleuse doit être une pro, elle a lissé ces lignes trop vite.'::text),
(388799,43200,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yemin ederim makyöz profesyonel ..., o çizgileri çok hızlı pürüzsüzleştirdi.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Kanka, yemin ederim makyöz profesyonel olmalı, o çizgileri çok hızlı pürüzsüzleştirdi.'::text),
(388800,43200,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszöm, a sminkes ... profi, olyan gyorsan elsimította azokat a vonalakat.'::text,'biztos'::text,'talán'::text,'nem lehet'::text,'Csajszi, esküszöm, a sminkes biztos profi, olyan gyorsan elsimította azokat a vonalakat.'::text),
(388803,43201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schwamm, ... die Linien geglättet hat, war orange.'::text,'der'::text,'wer'::text,'was'::text,'Der Schwamm, der die Linien geglättet hat, war orange.'::text),
(388807,43201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спонж, ... розгладив лінії, був помаранчевий.'::text,'який'::text,'хто'::text,'що'::text,'Спонж, який розгладив лінії, був помаранчевий.'::text),
(388806,43201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La esponja ... alisó las líneas era naranja.'::text,'que'::text,'quien'::text,'lo que'::text,'La esponja que alisó las líneas era naranja.'::text),
(388805,43201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''éponge ... a lissé les lignes était orange.'::text,'qui'::text,'qui'::text,'ce qui'::text,'L''éponge qui a lissé les lignes était orange.'::text),
(388808,43201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sünger, ... çizgileri pürüzsüzleştirdi, turuncuydu.'::text,'ki'::text,'kim'::text,'ne'::text,'Sünger, ki çizgileri pürüzsüzleştirdi, turuncuydu.'::text),
(388809,43201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szivacs, ... elsimította a vonalakat, narancssárga volt.'::text,'amely'::text,'aki'::text,'ami'::text,'A szivacs, amely elsimította a vonalakat, narancssárga volt.'::text),
(388812,43202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin sagte ihr, dass sie die Linien als Nächstes mit einem Pinsel ...'::text,'glätten würde'::text,'glätten wird'::text,'glättete'::text,'Die Visagistin sagte ihr, dass sie die Linien als Nächstes mit einem Pinsel glätten würde.'::text),
(388816,43202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка сказала їй, що далі ... лінії пензлем.'::text,'розгладить'::text,'розгладить'::text,'розгладила'::text,'Візажистка сказала їй, що далі розгладить лінії пензлем.'::text),
(388815,43202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilladora le dijo que después ... las líneas con una brocha.'::text,'alisaría'::text,'alisará'::text,'alisó'::text,'La maquilladora le dijo que después alisaría las líneas con una brocha.'::text),
(388814,43202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse lui a dit qu''elle ... ensuite les lignes au pinceau.'::text,'lisserait'::text,'lissera'::text,'a lissé'::text,'La maquilleuse lui a dit qu''elle lisserait ensuite les lignes au pinceau.'::text),
(388817,43202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz ona sıradaki adımda çizgileri fırçayla ... söyledi.'::text,'pürüzsüzleştireceğini'::text,'pürüzsüzleştireceğini'::text,'pürüzsüzleştirdiğini'::text,'Makyöz ona sıradaki adımda çizgileri fırçayla pürüzsüzleştireceğini söyledi.'::text),
(388818,43202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes azt mondta neki, hogy utána ecsettel ... a vonalakat.'::text,'simítja el'::text,'el fogja simítani'::text,'elsimította'::text,'A sminkes azt mondta neki, hogy utána ecsettel simítja el a vonalakat.'::text),
(388821,43203,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie diese Visagistin fand, ... sie ihr Make-up mit den Fingern glattzustreichen.'::text,'pflegte'::text,'war gewohnt'::text,'pflegte'::text,'Bevor sie diese Visagistin fand, pflegte sie ihr Make-up mit den Fingern glattzustreichen.'::text),
(388825,43203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона не знайшла цю візажистку, вона ... розгладжувати макіяж пальцями.'::text,'мала звичку'::text,'звикла'::text,'мала звичку'::text,'Поки вона не знайшла цю візажистку, вона мала звичку розгладжувати макіяж пальцями.'::text),
(388824,43203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de encontrar a esta maquilladora, ... alisarse el maquillaje con los dedos.'::text,'solía'::text,'estaba acostumbrada a'::text,'solía'::text,'Antes de encontrar a esta maquilladora, solía alisarse el maquillaje con los dedos.'::text),
(388823,43203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de trouver cette maquilleuse, elle ... lisser son maquillage avec les doigts.'::text,'avait l''habitude de'::text,'était habituée à'::text,'avait l''habitude de'::text,'Avant de trouver cette maquilleuse, elle avait l''habitude de lisser son maquillage avec les doigts.'::text),
(388826,43203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu makyözü bulmadan önce makyajını parmaklarıyla ...'::text,'pürüzsüzleştirirdi'::text,'pürüzsüzleştirmeye alışkındı'::text,'pürüzsüzleştirirdi'::text,'Bu makyözü bulmadan önce makyajını parmaklarıyla pürüzsüzleştirirdi.'::text),
(388827,43203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt megtalálta ezt a sminkest, ... elsimítani a sminkjét az ujjaival.'::text,'szokta'::text,'hozzá volt szokva'::text,'szokta'::text,'Mielőtt megtalálta ezt a sminkest, szokta elsimítani a sminkjét az ujjaival.'::text),
(388830,43204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Visagistin ... diese Linien immer weiter, irgendwie ikonisch.'::text,'glättet'::text,'glättet'::text,'glättet'::text,'Bro, die Visagistin glättet diese Linien immer weiter, irgendwie ikonisch.'::text),
(388834,43204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, візажистка все ... ці лінії, трохи культово.'::text,'розгладжує'::text,'розгладжує'::text,'розгладжує'::text,'Бро, візажистка все розгладжує ці лінії, трохи культово.'::text),
(388833,43204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la maquilladora sigue ... esas líneas, medio icónico.'::text,'alisando'::text,'alisar'::text,'alisa'::text,'Bro, la maquilladora sigue alisando esas líneas, medio icónico.'::text),
(388832,43204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la maquilleuse n''arrête pas de ... ces lignes, un peu iconique.'::text,'lisser'::text,'lisser'::text,'lisser'::text,'Frère, la maquilleuse n''arrête pas de lisser ces lignes, un peu iconique.'::text),
(388835,43204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, makyöz o çizgileri ... duruyor, bayağı efsane.'::text,'pürüzsüzleştirip'::text,'pürüzsüzleştirmek'::text,'pürüzsüzleştir'::text,'Kanka, makyöz o çizgileri pürüzsüzleştirip duruyor, bayağı efsane.'::text),
(388836,43204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a sminkes folyamatosan ... azokat a vonalakat, elég ikonikus.'::text,'simítja'::text,'simítja'::text,'simítja'::text,'Tesó, a sminkes folyamatosan simítja azokat a vonalakat, elég ikonikus.'::text),
(388839,43205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin ... seit dem Morgenbriefing bei 3 Kundinnen die Foundation geglättet.'::text,'hat'::text,'glättet'::text,'glättet'::text,'Die Visagistin hat seit dem Morgenbriefing bei 3 Kundinnen die Foundation geglättet.'::text),
(388843,43205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка ... тональний крем 3 клієнткам від ранкового брифінгу.'::text,'розгладила'::text,'розгладжує'::text,'розгладжує'::text,'Візажистка розгладила тональний крем 3 клієнткам від ранкового брифінгу.'::text),
(388842,43205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilladora ... la base de maquillaje de 3 clientas desde el briefing de la mañana.'::text,'ha alisado'::text,'alisa'::text,'está alisando'::text,'La maquilladora ha alisado la base de maquillaje de 3 clientas desde el briefing de la mañana.'::text),
(388841,43205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse ... le fond de teint de 3 clientes depuis le briefing du matin.'::text,'a lissé'::text,'lisse'::text,'est en train de lisser'::text,'La maquilleuse a lissé le fond de teint de 3 clientes depuis le briefing du matin.'::text),
(388844,43205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz sabah brifinginden beri 3 müşterinin fondötenini ...'::text,'pürüzsüzleştirdi'::text,'pürüzsüzleştirir'::text,'pürüzsüzleştiriyor'::text,'Makyöz sabah brifinginden beri 3 müşterinin fondötenini pürüzsüzleştirdi.'::text),
(388845,43205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes a reggeli eligazítás óta 3 ügyfélnek ... az alapozóját.'::text,'simította el'::text,'simítja el'::text,'simítja'::text,'A sminkes a reggeli eligazítás óta 3 ügyfélnek simította el az alapozóját.'::text),
(395400,43934,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein wahrer Visionär: Er ... seit Monaten Spinat-Smoothies, und der Geschmack ist immer noch perfekt.'::text,'macht'::text,'macht'::text,'macht'::text,'Ein wahrer Visionär: Er macht seit Monaten Spinat-Smoothies, und der Geschmack ist immer noch perfekt.'::text),
(395404,43934,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній візіонер: він ... шпинатні смузі вже кілька місяців, і смак досі ідеальний.'::text,'робить'::text,'робить'::text,'робить'::text,'Справжній візіонер: він робить шпинатні смузі вже кілька місяців, і смак досі ідеальний.'::text),
(395403,43934,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un visionario: ... smoothies de espinaca desde hace meses, y el sabor sigue siendo perfecto.'::text,'ha estado haciendo'::text,'está haciendo'::text,'hace'::text,'Todo un visionario: ha estado haciendo smoothies de espinaca desde hace meses, y el sabor sigue siendo perfecto.'::text),
(395402,43934,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai visionnaire : il ... des smoothies aux épinards depuis des mois, et le goût est toujours parfait.'::text,'fait'::text,'fait'::text,'fait'::text,'Un vrai visionnaire : il fait des smoothies aux épinards depuis des mois, et le goût est toujours parfait.'::text),
(395405,43934,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir vizyoner: aylardır ıspanaklı smoothie ... ve tadı hâlâ mükemmel.'::text,'yapıyor'::text,'yapıyor'::text,'yapar'::text,'Gerçek bir vizyoner: aylardır ıspanaklı smoothie yapıyor ve tadı hâlâ mükemmel.'::text),
(395406,43934,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi látnok: hónapok óta ... spenótos smoothie-kat, és az íze még mindig tökéletes.'::text,'készít'::text,'készít'::text,'készít'::text,'Igazi látnok: hónapok óta készít spenótos smoothie-kat, és az íze még mindig tökéletes.'::text),
(395409,43935,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Manieren, klar: Während er den Smoothie ..., landete sein Geschmack auf seiner ganzen Lippe.'::text,'trank'::text,'trank'::text,'getrunken hat'::text,'Tolle Manieren, klar: Während er den Smoothie trank, landete sein Geschmack auf seiner ganzen Lippe.'::text),
(395413,43935,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудові манери, звісно: поки він ... смузі, його смак розмазався по всій губі.'::text,'пив'::text,'випив'::text,'випив'::text,'Чудові манери, звісно: поки він пив смузі, його смак розмазався по всій губі.'::text),
(395412,43935,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué modales, obviamente: mientras ... el smoothie, su sabor le quedó por todo el labio.'::text,'se tomaba'::text,'se tomó'::text,'se ha tomado'::text,'Qué modales, obviamente: mientras se tomaba el smoothie, su sabor le quedó por todo el labio.'::text),
(395411,43935,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De super manières, évidemment : pendant qu''il ... le smoothie, son goût s''est étalé sur toute sa lèvre.'::text,'buvait'::text,'a bu'::text,'a bu'::text,'De super manières, évidemment : pendant qu''il buvait le smoothie, son goût s''est étalé sur toute sa lèvre.'::text),
(395414,43935,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika görgü, tabii: smoothie''yi ... tadı bütün dudağına bulaştı.'::text,'içerken'::text,'içti'::text,'içmiş'::text,'Harika görgü, tabii: smoothie''yi içerken tadı bütün dudağına bulaştı.'::text),
(395415,43935,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek modor, nyilván: miközben ... a smoothie-t, az íze szétkenődött az egész száján.'::text,'itta'::text,'megitta'::text,'megitta'::text,'Remek modor, nyilván: miközben itta a smoothie-t, az íze szétkenődött az egész száján.'::text),
(395418,43936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... heute drei Smoothies gemacht, und er liebt den Geschmack immer noch.'::text,'hat'::text,'hat'::text,'macht'::text,'Er hat heute drei Smoothies gemacht, und er liebt den Geschmack immer noch.'::text),
(395422,43936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він ... три смузі, і досі обожнює смак.'::text,'зробив'::text,'робив'::text,'робить'::text,'Сьогодні він зробив три смузі, і досі обожнює смак.'::text),
(395421,43936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... tres smoothies y todavía le encanta el sabor.'::text,'ha hecho'::text,'ha estado haciendo'::text,'está haciendo'::text,'Hoy ha hecho tres smoothies y todavía le encanta el sabor.'::text),
(395420,43936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... trois smoothies aujourd''hui, et il adore toujours le goût.'::text,'a fait'::text,'fait'::text,'est en train de faire'::text,'Il a fait trois smoothies aujourd''hui, et il adore toujours le goût.'::text),
(395423,43936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün üç smoothie ... ve tadına hâlâ bayılıyor.'::text,'yaptı'::text,'yapıp durdu'::text,'yapıyor'::text,'Bugün üç smoothie yaptı ve tadına hâlâ bayılıyor.'::text),
(395424,43936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma már három smoothie-t ..., és még mindig imádja az ízét.'::text,'csinált'::text,'csinálgatott'::text,'csinál'::text,'Ma már három smoothie-t csinált, és még mindig imádja az ízét.'::text),
(395427,43937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, der Geschmack sei perfekt, weil er genug Mango ...'::text,'reingetan hatte'::text,'reingetan hat'::text,'reintut'::text,'Er sagte, der Geschmack sei perfekt, weil er genug Mango reingetan hatte.'::text),
(395431,43937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що смак був ідеальний, бо він ... достатньо манго.'::text,'додав'::text,'додав'::text,'додає'::text,'Він сказав, що смак був ідеальний, бо він додав достатньо манго.'::text),
(395430,43937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el sabor era perfecto porque ... suficiente mango.'::text,'había echado'::text,'ha echado'::text,'echa'::text,'Dijo que el sabor era perfecto porque había echado suficiente mango.'::text),
(395429,43937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que le goût était parfait parce qu''il ... assez de mangue.'::text,'avait ajouté'::text,'a ajouté'::text,'ajoute'::text,'Il a dit que le goût était parfait parce qu''il avait ajouté assez de mangue.'::text),
(395432,43937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeterince mango ... için tadın mükemmel olduğunu söyledi.'::text,'eklemiş olduğu'::text,'eklediği'::text,'eklediği'::text,'Yeterince mango eklemiş olduğu için tadın mükemmel olduğunu söyledi.'::text),
(395433,43937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, tökéletes az íze, mert elég mangót ...'::text,'tett bele'::text,'tett bele'::text,'tesz bele'::text,'Azt mondta, tökéletes az íze, mert elég mangót tett bele.'::text),
(395436,43938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er mehr Spinat reintut, ... der Geschmack weniger süß.'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn er mehr Spinat reintut, wird der Geschmack weniger süß.'::text),
(395440,43938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він додасть більше шпинату, смак ... менш солодким.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо він додасть більше шпинату, смак буде менш солодким.'::text),
(395439,43938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si añade más espinaca, el sabor ... menos dulce.'::text,'será'::text,'sería'::text,'era'::text,'Si añade más espinaca, el sabor será menos dulce.'::text),
(395438,43938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ajoute plus d''épinards, le goût ... moins sucré.'::text,'sera'::text,'serait'::text,'était'::text,'S''il ajoute plus d''épinards, le goût sera moins sucré.'::text),
(395441,43938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha fazla ıspanak eklerse tadı daha az tatlı ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Daha fazla ıspanak eklerse tadı daha az tatlı olacak.'::text),
(395442,43938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha több spenótot tesz bele, az íze kevésbé ... édes.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha több spenótot tesz bele, az íze kevésbé lesz édes.'::text),
(395445,43939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Smoothie keinen Geschmack hätte, ... er nach nichts schmecken, weil es keinen Geschmack gäbe.'::text,'würde'::text,'wird'::text,'schmeckt'::text,'Wenn der Smoothie keinen Geschmack hätte, würde er nach nichts schmecken, weil es keinen Geschmack gäbe.'::text),
(395449,43939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби смузі не мав смаку, він ... нічим, бо смаку б не було.'::text,'смакував би'::text,'смакуватиме'::text,'смакує'::text,'Якби смузі не мав смаку, він смакував би нічим, бо смаку б не було.'::text),
(395448,43939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el smoothie no tuviera sabor, ... a nada, porque no habría sabor.'::text,'sabría'::text,'sabrá'::text,'sabe'::text,'Si el smoothie no tuviera sabor, sabría a nada, porque no habría sabor.'::text),
(395447,43939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le smoothie n''avait aucun goût, il ... le goût de rien, parce qu''il n''y aurait pas de goût.'::text,'aurait'::text,'aura'::text,'a'::text,'Si le smoothie n''avait aucun goût, il aurait le goût de rien, parce qu''il n''y aurait pas de goût.'::text),
(395450,43939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Smoothie''nin hiç tadı olmasaydı, tadı hiçbir şey gibi ..., çünkü hiç tat olmazdı.'::text,'olurdu'::text,'olacak'::text,'oluyor'::text,'Smoothie''nin hiç tadı olmasaydı, tadı hiçbir şey gibi olurdu, çünkü hiç tat olmazdı.'::text),
(395451,43939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a smoothie-nak nem lenne íze, semmi ízű ..., mert nem lenne íze.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a smoothie-nak nem lenne íze, semmi ízű lenne, mert nem lenne íze.'::text),
(395454,43940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der süße Geschmack ... von der Mango und der Banane erzeugt, wie das Grinsen des Subjekts zeigt.'::text,'wird'::text,'erzeugt'::text,'erzeugte'::text,'Der süße Geschmack wird von der Mango und der Banane erzeugt, wie das Grinsen des Subjekts zeigt.'::text),
(395458,43940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Солодкий смак ... манго та бананом, на що вказує усмішка суб''єкта.'::text,'створюється'::text,'створює'::text,'створював'::text,'Солодкий смак створюється манго та бананом, на що вказує усмішка суб''єкта.'::text),
(395457,43940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sabor dulce ... por el mango y el plátano, como indica la sonrisa del sujeto.'::text,'es producido'::text,'produce'::text,'estaba produciendo'::text,'El sabor dulce es producido por el mango y el plátano, como indica la sonrisa del sujeto.'::text),
(395456,43940,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le goût sucré ... par la mangue et la banane, comme l''indique le sourire du sujet.'::text,'est produit'::text,'produit'::text,'produisait'::text,'Le goût sucré est produit par la mangue et la banane, comme l''indique le sourire du sujet.'::text),
(395459,43940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatlı tat, deneğin sırıtışının gösterdiği gibi, mango ve muz tarafından ...'::text,'üretiliyor'::text,'üretiyor'::text,'üretiyordu'::text,'Tatlı tat, deneğin sırıtışının gösterdiği gibi, mango ve muz tarafından üretiliyor.'::text),
(395460,43940,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az édes ízt a mangó és a banán ..., ahogy az alany vigyora is mutatja.'::text,'hozza létre'::text,'hozza létre'::text,'hozta létre'::text,'Az édes ízt a mangó és a banán hozza létre, ahogy az alany vigyora is mutatja.'::text),
(395463,43941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spinat ... in den Mixbecher gegeben, aber der Geschmack blieb süß.'::text,'wurde'::text,'gab'::text,'gebend'::text,'Spinat wurde in den Mixbecher gegeben, aber der Geschmack blieb süß.'::text),
(395467,43941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шпинат ... в чашу блендера, але смак лишився солодким.'::text,'було додано'::text,'додав'::text,'додаючи'::text,'Шпинат було додано в чашу блендера, але смак лишився солодким.'::text),
(395466,43941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La espinaca ... a la jarra, pero el sabor siguió siendo dulce.'::text,'fue añadida'::text,'añadió'::text,'añadiendo'::text,'La espinaca fue añadida a la jarra, pero el sabor siguió siendo dulce.'::text),
(395465,43941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des épinards ... dans le bol, mais le goût est resté sucré.'::text,'ont été ajoutés'::text,'ont ajouté'::text,'ajoutant'::text,'Des épinards ont été ajoutés dans le bol, mais le goût est resté sucré.'::text),
(395468,43941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürahiye ıspanak ..., ama tadı tatlı kaldı.'::text,'eklendi'::text,'ekledi'::text,'ekleyerek'::text,'Sürahiye ıspanak eklendi, ama tadı tatlı kaldı.'::text),
(395469,43941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spenótot is ... a kancsóba, de az íze édes maradt.'::text,'tettek'::text,'tett'::text,'téve'::text,'Spenótot is tettek a kancsóba, de az íze édes maradt.'::text),
(395472,43942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast „Perfekt“ gesagt, also ... der Geschmack der Hammer sein. Ehrlich, Respekt.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Du hast „Perfekt“ gesagt, also muss der Geschmack der Hammer sein. Ehrlich, Respekt.'::text),
(395476,43942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав «Ідеально», тож смак ... бути неймовірним. Чесно, респект.'::text,'має'::text,'може'::text,'не може'::text,'Ти сказав «Ідеально», тож смак має бути неймовірним. Чесно, респект.'::text),
(395475,43942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste «Perfecto», así que el sabor ... ser increíble. La verdad, respeto.'::text,'tiene que'::text,'podría'::text,'no puede'::text,'Dijiste «Perfecto», así que el sabor tiene que ser increíble. La verdad, respeto.'::text),
(395474,43942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit « Parfait », donc le goût ... être incroyable. Franchement, respect.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Tu as dit « Parfait », donc le goût doit être incroyable. Franchement, respect.'::text),
(395477,43942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'“Mükemmel” dedin, yani tadı harika ...; açıkçası, helal olsun.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'“Mükemmel” dedin, yani tadı harika olmalı; açıkçası, helal olsun.'::text),
(395478,43942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, „Tökéletes”, szóval az íze ... elképesztő. Őszintén, respekt.'::text,'biztos'::text,'talán'::text,'nem lehet'::text,'Azt mondtad, „Tökéletes”, szóval az íze biztos elképesztő. Őszintén, respekt.'::text),
(335217,37247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie blind herum, als sie die roten Becher umgeworfen hat.'::text,'stolperte'::text,'stolperte'::text,'ist gestolpert'::text,'Girl, angeblich stolperte sie blind herum, als sie die roten Becher umgeworfen hat.'::text),
(335221,37247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... наосліп, коли перекинула червоні стаканчики.'::text,'спотикалася'::text,'спіткнулася'::text,'спіткнулася'::text,'Подруго, кажуть, вона спотикалася наосліп, коли перекинула червоні стаканчики.'::text),
(335220,37247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... a ciegas cuando tiró los vasos rojos.'::text,'iba tropezando'::text,'tropezó'::text,'ha tropezado'::text,'Tía, al parecer iba tropezando a ciegas cuando tiró los vasos rojos.'::text),
(335219,37247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... à l''aveugle quand elle a renversé les gobelets rouges.'::text,'titubait'::text,'a trébuché'::text,'a trébuché'::text,'Meuf, apparemment elle titubait à l''aveugle quand elle a renversé les gobelets rouges.'::text),
(335222,37247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan kırmızı bardakları devirdiğinde gözü kapalı ...'::text,'sendeliyormuş'::text,'sendeledi'::text,'sendelemiş'::text,'Kızım, anlaşılan kırmızı bardakları devirdiğinde gözü kapalı sendeliyormuş.'::text),
(335223,37247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag vakon ..., amikor feldöntötte a piros poharakat.'::text,'botladozott'::text,'megbotlott'::text,'megbotlott'::text,'Csajszi, állítólag vakon botladozott, amikor feldöntötte a piros poharakat.'::text),
(335226,37248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du ... seit zehn Minuten blind herum und lächelst immer noch.'::text,'läufst'::text,'läufst'::text,'läufst'::text,'Ganz ehrlich, du läufst seit zehn Minuten blind herum und lächelst immer noch.'::text),
(335230,37248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... наосліп уже десять хвилин і досі усміхаєшся.'::text,'ходиш'::text,'ходиш'::text,'ходиш'::text,'Чесно, ти ходиш наосліп уже десять хвилин і досі усміхаєшся.'::text),
(335229,37248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... a ciegas desde hace diez minutos y sigues sonriendo.'::text,'has estado caminando'::text,'estás caminando'::text,'caminas'::text,'No voy a mentir, has estado caminando a ciegas desde hace diez minutos y sigues sonriendo.'::text),
(335228,37248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... à l''aveugle depuis dix minutes et tu souris encore.'::text,'marches'::text,'marches'::text,'marches'::text,'Je vais pas mentir, tu marches à l''aveugle depuis dix minutes et tu souris encore.'::text),
(335231,37248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, on dakikadır gözü kapalı ... ve hâlâ gülümsüyorsun.'::text,'yürüyorsun'::text,'yürüyorsun'::text,'yürürsün'::text,'Yalan yok, on dakikadır gözü kapalı yürüyorsun ve hâlâ gülümsüyorsun.'::text),
(335232,37248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, tíz perce ... vakon, és még mindig mosolyogsz.'::text,'sétálsz'::text,'sétálsz'::text,'sétálsz'::text,'Nem hazudok, tíz perce sétálsz vakon, és még mindig mosolyogsz.'::text),
(335235,37249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... blind mit ausgestreckten Händen nach vorn, als jemand den Couchtisch verschob.'::text,'ging'::text,'ging'::text,'ist gegangen'::text,'Sie ging blind mit ausgestreckten Händen nach vorn, als jemand den Couchtisch verschob.'::text),
(335239,37249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... наосліп уперед з витягнутими руками, коли хтось пересунув журнальний столик.'::text,'йшла'::text,'пішла'::text,'пішла'::text,'Вона йшла наосліп уперед з витягнутими руками, коли хтось пересунув журнальний столик.'::text),
(335238,37249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a ciegas hacia delante con las manos extendidas cuando alguien movió la mesita.'::text,'Caminaba'::text,'Caminó'::text,'Ha caminado'::text,'Caminaba a ciegas hacia delante con las manos extendidas cuando alguien movió la mesita.'::text),
(335237,37249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... à l''aveugle, les mains tendues, quand quelqu''un a déplacé la table basse.'::text,'avançait'::text,'a avancé'::text,'a avancé'::text,'Elle avançait à l''aveugle, les mains tendues, quand quelqu''un a déplacé la table basse.'::text),
(335240,37249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri sehpayı kaydırdığında o gözü kapalı, elleri önde ileri ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürümüş'::text,'Biri sehpayı kaydırdığında o gözü kapalı, elleri önde ileri yürüyordu.'::text),
(335241,37249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vakon, kinyújtott kézzel ... előre, amikor valaki elmozdította a dohányzóasztalt.'::text,'ment'::text,'indult'::text,'ment'::text,'Vakon, kinyújtott kézzel ment előre, amikor valaki elmozdította a dohányzóasztalt.'::text),
(335244,37250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... die blinden Gäste drei rote Becher vom Couchtisch geworfen.'::text,'haben'::text,'haben'::text,'werfen'::text,'Bisher haben die blinden Gäste drei rote Becher vom Couchtisch geworfen.'::text),
(335248,37250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки що сліпі гості ... з журнального столика три червоні стаканчики.'::text,'скинули'::text,'скидали'::text,'скидають'::text,'Поки що сліпі гості скинули з журнального столика три червоні стаканчики.'::text),
(335247,37250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, los invitados a ciegas ... tres vasos rojos de la mesita.'::text,'han tirado'::text,'han estado tirando'::text,'están tirando'::text,'Hasta ahora, los invitados a ciegas han tirado tres vasos rojos de la mesita.'::text),
(335246,37250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, les invités aveugles ... trois gobelets rouges de la table basse.'::text,'ont fait tomber'::text,'font tomber'::text,'sont en train de faire tomber'::text,'Jusqu''ici, les invités aveugles ont fait tomber trois gobelets rouges de la table basse.'::text),
(335249,37250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar gözü kapalı misafirler sehpadan üç kırmızı bardak ...'::text,'düşürdü'::text,'düşürüp durdu'::text,'düşürüyor'::text,'Şimdiye kadar gözü kapalı misafirler sehpadan üç kırmızı bardak düşürdü.'::text),
(335250,37250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig a vak vendégek három piros poharat ... le a dohányzóasztalról.'::text,'vertek'::text,'vertek'::text,'vernek'::text,'Eddig a vak vendégek három piros poharat vertek le a dohányzóasztalról.'::text),
(335262,37252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 21 Uhr ... die Subjekte blind durch den Raum stolpern, wie typischerweise beobachtet.'::text,'werden'::text,'werden'::text,'stolpern'::text,'Morgen um 21 Uhr werden die Subjekte blind durch den Raum stolpern, wie typischerweise beobachtet.'::text),
(335266,37252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о 21:00 суб''єкти ... наосліп по кімнаті, як це типово спостерігається.'::text,'спотикатимуться'::text,'спіткнуться'::text,'спотикаються'::text,'Завтра о 21:00 суб''єкти спотикатимуться наосліп по кімнаті, як це типово спостерігається.'::text),
(335265,37252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las 21:00, los sujetos ... a ciegas por la sala, como se observa típicamente.'::text,'estarán tropezando'::text,'tropezarán'::text,'tropiezan'::text,'Mañana a las 21:00, los sujetos estarán tropezando a ciegas por la sala, como se observa típicamente.'::text),
(335264,37252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 21 h, les sujets ... à l''aveugle dans la pièce, comme on l''observe typiquement.'::text,'seront en train de tituber'::text,'tituberont'::text,'titubent'::text,'Demain à 21 h, les sujets seront en train de tituber à l''aveugle dans la pièce, comme on l''observe typiquement.'::text),
(335267,37252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat 21.00''de denekler, tipik olarak gözlemlendiği gibi, odada gözü kapalı ...'::text,'sendeliyor olacak'::text,'sendeleyecek'::text,'sendeliyor'::text,'Yarın saat 21.00''de denekler, tipik olarak gözlemlendiği gibi, odada gözü kapalı sendeliyor olacak.'::text),
(335268,37252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap 21 órakor az alanyok vakon ... a szobában, ahogy az jellemzően megfigyelhető.'::text,'fognak botladozni'::text,'botladoznak majd'::text,'botladoznak'::text,'Holnap 21 órakor az alanyok vakon fognak botladozni a szobában, ahogy az jellemzően megfigyelhető.'::text),
(335271,37253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist das Schlimmste! Blind oder nicht, ich verspreche, ich ... die Piñata nächstes Mal!'::text,'treffe'::text,'treffe'::text,'treffe'::text,'Das ist das Schlimmste! Blind oder nicht, ich verspreche, ich treffe die Piñata nächstes Mal!'::text),
(335275,37253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це найгірше! Наосліп чи ні, обіцяю, що наступного разу ... ту піньяту!'::text,'влучу в'::text,'влучатиму в'::text,'влучаю в'::text,'Це найгірше! Наосліп чи ні, обіцяю, що наступного разу влучу в ту піньяту!'::text),
(335274,37253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esto es lo peor! ¡A ciegas o no, te prometo que la próxima vez le ... a esa piñata!'::text,'daré'::text,'estaré dando'::text,'doy'::text,'¡Esto es lo peor! ¡A ciegas o no, te prometo que la próxima vez le daré a esa piñata!'::text),
(335273,37253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le pire ! Aveugle ou pas, je promets que la prochaine fois je ... cette piñata !'::text,'frapperai'::text,'serai en train de frapper'::text,'frappe'::text,'C''est le pire ! Aveugle ou pas, je promets que la prochaine fois je frapperai cette piñata !'::text),
(335276,37253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu en kötüsü! Gözüm kapalı olsun olmasın, söz veriyorum, bir dahaki sefere o piñataya ...!'::text,'vuracağım'::text,'vuruyor olacağım'::text,'vuruyorum'::text,'Bu en kötüsü! Gözüm kapalı olsun olmasın, söz veriyorum, bir dahaki sefere o piñataya vuracağım!'::text),
(335277,37253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a legrosszabb! Vakon vagy sem, ígérem, legközelebb ... azt a piñatát!'::text,'eltalálom'::text,'ütni fogom'::text,'ütöm'::text,'Ez a legrosszabb! Vakon vagy sem, ígérem, legközelebb eltalálom azt a piñatát!'::text),
(335280,37254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... Partyspiele mit verbundenen Augen, aber jetzt haben sie mir den Abend total ruiniert!'::text,'liebte früher'::text,'würde lieben'::text,'war gewohnt zu lieben'::text,'Ich liebte früher Partyspiele mit verbundenen Augen, aber jetzt haben sie mir den Abend total ruiniert!'::text),
(335284,37254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я ... ігри наосліп на вечірках, але тепер вони повністю зіпсували мені вечір!'::text,'колись любив'::text,'колись любив'::text,'звик любити'::text,'Я колись любив ігри наосліп на вечірках, але тепер вони повністю зіпсували мені вечір!'::text),
(335283,37254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... encantarme los juegos a ciegas en las fiestas, pero ahora me han arruinado la noche por completo!'::text,'Solían'::text,'Solían'::text,'Estaba acostumbrado a'::text,'¡Solían encantarme los juegos a ciegas en las fiestas, pero ahora me han arruinado la noche por completo!'::text),
(335282,37254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, ... les jeux à l''aveugle en soirée, mais maintenant ils m''ont complètement gâché la nuit !'::text,'j''adorais'::text,'j''adorerais'::text,'j''avais l''habitude d''adorer'::text,'Avant, j''adorais les jeux à l''aveugle en soirée, mais maintenant ils m''ont complètement gâché la nuit !'::text),
(335285,37254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden gözü kapalı parti oyunlarına ..., ama şimdi gecemi tamamen mahvettiler!'::text,'bayılırdım'::text,'bayılırdım'::text,'bayılmaya alışkındım'::text,'Eskiden gözü kapalı parti oyunlarına bayılırdım, ama şimdi gecemi tamamen mahvettiler!'::text),
(335286,37254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a vakon játszós bulis játékokat, de most teljesen tönkretették az estémet!'::text,'imádtam'::text,'imádtam volna'::text,'hozzá voltam szokva, hogy imádjam'::text,'Régen imádtam a vakon játszós bulis játékokat, de most teljesen tönkretették az estémet!'::text),
(335289,37255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie wieder! Ich weigere mich, noch ein einziges Mal blind durch dieses Wohnzimmer ...!'::text,'zu stolpern'::text,'stolpernd'::text,'stolpern'::text,'Nie wieder! Ich weigere mich, noch ein einziges Mal blind durch dieses Wohnzimmer zu stolpern!'::text),
(335293,37255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Більше ніколи! Я відмовляюся ще раз ... наосліп по цій вітальні!'::text,'спотикатися'::text,'спотикання'::text,'спотикатися'::text,'Більше ніколи! Я відмовляюся ще раз спотикатися наосліп по цій вітальні!'::text),
(335292,37255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca más! ¡Me niego ... a ciegas por este salón una vez más!'::text,'a tropezar'::text,'tropezando'::text,'tropezar'::text,'¡Nunca más! ¡Me niego a tropezar a ciegas por este salón una vez más!'::text),
(335291,37255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus jamais ! Je refuse ... à l''aveugle dans ce salon une fois de plus !'::text,'de tituber'::text,'titubant'::text,'tituber'::text,'Plus jamais ! Je refuse de tituber à l''aveugle dans ce salon une fois de plus !'::text),
(335294,37255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla! Bu salonda bir kez daha gözü kapalı ... reddediyorum!'::text,'sendelemeyi'::text,'sendeleyerek'::text,'sendele'::text,'Bir daha asla! Bu salonda bir kez daha gözü kapalı sendelemeyi reddediyorum!'::text),
(335295,37255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha többé! Nem vagyok hajlandó még egyszer vakon ... ebben a nappaliban!'::text,'botladozni'::text,'botladozva'::text,'botladozni'::text,'Soha többé! Nem vagyok hajlandó még egyszer vakon botladozni ebben a nappaliban!'::text),
(335298,37256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, angeblich ... sie gerade blind herum und sucht die Snacks.'::text,'irrt'::text,'irrt'::text,'ist geirrt'::text,'Okay also, angeblich irrt sie gerade blind herum und sucht die Snacks.'::text),
(335302,37256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, вона просто зараз ... наосліп у пошуках снеків.'::text,'блукає'::text,'блукає'::text,'поблукала'::text,'Отже, кажуть, вона просто зараз блукає наосліп у пошуках снеків.'::text),
(335301,37256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, al parecer ahora mismo ... a ciegas buscando los snacks.'::text,'está deambulando'::text,'deambula'::text,'ha deambulado'::text,'Ok, al parecer ahora mismo está deambulando a ciegas buscando los snacks.'::text),
(335300,37256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, apparemment là, elle ... à l''aveugle en cherchant les snacks.'::text,'erre'::text,'erre'::text,'a erré'::text,'Ok alors, apparemment là, elle erre à l''aveugle en cherchant les snacks.'::text),
(335303,37256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan şu an atıştırmalıkları arayarak gözü kapalı ...'::text,'dolaşıyor'::text,'dolaşır'::text,'dolaştı'::text,'Tamam, anlaşılan şu an atıştırmalıkları arayarak gözü kapalı dolaşıyor.'::text),
(335304,37256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag most épp vakon ..., és a nasit keresi.'::text,'bolyong'::text,'bolyong'::text,'bolyongott'::text,'Oké, szóval állítólag most épp vakon bolyong, és a nasit keresi.'::text),
(398505,44279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Pflaster, ... ihr Freund ihr gab, war die einzige Behandlung, die sie hatten.'::text,'das'::text,'der'::text,'was'::text,'Das Pflaster, das ihr Freund ihr gab, war die einzige Behandlung, die sie hatten.'::text),
(398509,44279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пластир, ... їй дав друг, був єдиним засобом лікування, який у них був.'::text,'який'::text,'хто'::text,'що'::text,'Пластир, який їй дав друг, був єдиним засобом лікування, який у них був.'::text),
(398508,44279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tirita ... le dio su amigo era el único tratamiento que tenían.'::text,'que'::text,'quien'::text,'lo que'::text,'La tirita que le dio su amigo era el único tratamiento que tenían.'::text),
(398507,44279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pansement ... son ami lui a donné était le seul traitement qu''ils avaient.'::text,'que'::text,'qui'::text,'ce que'::text,'Le pansement que son ami lui a donné était le seul traitement qu''ils avaient.'::text),
(398510,44279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yara bandı, ... arkadaşı ona verdi, ellerindeki tek tedaviydi.'::text,'ki'::text,'kim'::text,'ne'::text,'Yara bandı, ki arkadaşı ona verdi, ellerindeki tek tedaviydi.'::text),
(398511,44279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sebtapasz, ... a barátja adott neki, volt az egyetlen kezelés, ami náluk volt.'::text,'amit'::text,'aki'::text,'ami'::text,'A sebtapasz, amit a barátja adott neki, volt az egyetlen kezelés, ami náluk volt.'::text),
(398514,44280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Freund sagte, die Blase ... eine Behandlung, bevor sie weitergingen.'::text,'brauchte'::text,'hat gebraucht'::text,'braucht'::text,'Ihr Freund sagte, die Blase brauchte eine Behandlung, bevor sie weitergingen.'::text),
(398518,44280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її друг сказав, що пухир ... обробки, перш ніж вони підуть далі.'::text,'потребує'::text,'потребував'::text,'потребує'::text,'Її друг сказав, що пухир потребує обробки, перш ніж вони підуть далі.'::text),
(398517,44280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amigo dijo que la ampolla ... tratamiento antes de seguir caminando.'::text,'necesitaba'::text,'ha necesitado'::text,'está necesitando'::text,'Su amigo dijo que la ampolla necesitaba tratamiento antes de seguir caminando.'::text),
(398516,44280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son ami a dit que l''ampoule ... un traitement avant de repartir.'::text,'nécessitait'::text,'a nécessité'::text,'nécessite'::text,'Son ami a dit que l''ampoule nécessitait un traitement avant de repartir.'::text),
(398519,44280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı, yola devam etmeden önce su toplamasının tedaviye ... söyledi.'::text,'ihtiyacı olduğunu'::text,'ihtiyacı olmuş olduğunu'::text,'ihtiyacı olduğunu'::text,'Arkadaşı, yola devam etmeden önce su toplamasının tedaviye ihtiyacı olduğunu söyledi.'::text),
(398520,44280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátja azt mondta, hogy a vízhólyag kezelésre ..., mielőtt továbbmennek.'::text,'szorul'::text,'szorult'::text,'szorul'::text,'A barátja azt mondta, hogy a vízhólyag kezelésre szorul, mielőtt továbbmennek.'::text),
(398523,44281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dieser Wanderung ... sie nie ein Mittel gegen Blasen dabei.'::text,'hatte'::text,'war gewohnt'::text,'hätte'::text,'Vor dieser Wanderung hatte sie nie ein Mittel gegen Blasen dabei.'::text),
(398527,44281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цього походу вона ... з собою жодних засобів від пухирів.'::text,'не носила'::text,'не звикла носити'::text,'не носила б'::text,'До цього походу вона не носила з собою жодних засобів від пухирів.'::text),
(398526,44281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de esta excursión, no ... llevar ningún tratamiento para ampollas.'::text,'solía'::text,'estaba acostumbrada a'::text,'solía'::text,'Antes de esta excursión, no solía llevar ningún tratamiento para ampollas.'::text),
(398525,44281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant cette rando, elle ... de traitement pour les ampoules sur elle.'::text,'n''avait pas l''habitude d''emporter'::text,'n''était pas habituée à emporter'::text,'n''emportait pas'::text,'Avant cette rando, elle n''avait pas l''habitude d''emporter de traitement pour les ampoules sur elle.'::text),
(398528,44281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yürüyüşten önce yanında su toplaması için hiçbir tedavi ...'::text,'taşımazdı'::text,'taşımaya alışkın değildi'::text,'taşımazdı'::text,'Bu yürüyüşten önce yanında su toplaması için hiçbir tedavi taşımazdı.'::text),
(398529,44281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'E túra előtt nem ... magánál semmit a vízhólyagok kezelésére.'::text,'szokott vinni'::text,'volt hozzászokva, hogy vigyen'::text,'vitt volna'::text,'E túra előtt nem szokott vinni magánál semmit a vízhólyagok kezelésére.'::text),
(398541,44283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Behandlung kann diese Wanderung vor der totalen Katastrophe retten, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Keine Behandlung kann diese Wanderung vor der totalen Katastrophe retten, oder?'::text),
(398545,44283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодне лікування не врятує цей похід від повної катастрофи, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Жодне лікування не врятує цей похід від повної катастрофи, правда?'::text),
(398544,44283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ningún tratamiento puede salvar esta excursión del desastre total, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Ningún tratamiento puede salvar esta excursión del desastre total, ¿verdad?'::text),
(398543,44283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aucun traitement ne peut sauver cette rando du désastre total, ...'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Aucun traitement ne peut sauver cette rando du désastre total, n''est-ce pas ?'::text),
(398546,44283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiçbir tedavi bu yürüyüşü tam bir felaketten kurtaramaz, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Hiçbir tedavi bu yürüyüşü tam bir felaketten kurtaramaz, değil mi?'::text),
