(398550,44284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, sie meinte, sie hatte nichts gegen Blasen dabei, und ...'::text,'er auch nicht.'::text,'er auch nicht.'::text,'er auch.'::text,'Girl, sie meinte, sie hatte nichts gegen Blasen dabei, und er auch nicht.'::text),
(398554,44284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що не мала з собою нічого від пухирів, і ...'::text,'він теж ні.'::text,'він теж ні.'::text,'він теж.'::text,'Подруго, вона сказала, що не мала з собою нічого від пухирів, і він теж ні.'::text),
(398553,44284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dijo que no llevaba nada para las ampollas, y ...'::text,'él tampoco.'::text,'él tampoco.'::text,'él también.'::text,'Tía, dijo que no llevaba nada para las ampollas, y él tampoco.'::text),
