(398555,44284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, yanında su toplamasına karşı hiçbir şey olmadığını söyledi ve ...'::text,'onda da yoktu.'::text,'onda da yoktu.'::text,'onda da vardı.'::text,'Kızım, yanında su toplamasına karşı hiçbir şey olmadığını söyledi ve onda da yoktu.'::text),
(398556,44284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, nem volt nála semmi vízhólyag ellen, és ...'::text,'nála sem.'::text,'nála sem.'::text,'nála is.'::text,'Csajszi, azt mondta, nem volt nála semmi vízhólyag ellen, és nála sem.'::text),
(398559,44285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich ... sie stundenlang gehumpelt, bevor sie für eine Behandlung anhielt.'::text,'war'::text,'ist'::text,'humpelt'::text,'Rate mal, angeblich war sie stundenlang gehumpelt, bevor sie für eine Behandlung anhielt.'::text),
(398563,44285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, вона ... кілька годин, перш ніж зупинилася на обробку.'::text,'кульгала'::text,'кульгає'::text,'кульгає'::text,'Уяви, кажуть, вона кульгала кілька годин, перш ніж зупинилася на обробку.'::text),
(398562,44285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, al parecer ... durante horas antes de parar para curarse.'::text,'había estado cojeando'::text,'ha estado cojeando'::text,'está cojeando'::text,'Adivina qué, al parecer había estado cojeando durante horas antes de parar para curarse.'::text),
(398561,44285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment elle ... depuis des heures avant de s''arrêter pour se soigner.'::text,'boitait'::text,'a boité'::text,'boite'::text,'Devine quoi, apparemment elle boitait depuis des heures avant de s''arrêter pour se soigner.'::text),
(398564,44285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, anlaşılan tedavi için durmadan önce saatlerce ...'::text,'topallıyormuş'::text,'topallıyor'::text,'topallıyor'::text,'Tahmin et ne oldu, anlaşılan tedavi için durmadan önce saatlerce topallıyormuş.'::text),
(398565,44285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag órákig ..., mielőtt megállt ellátásra.'::text,'sántikált'::text,'sántikál'::text,'sántikál'::text,'Képzeld, állítólag órákig sántikált, mielőtt megállt ellátásra.'::text),
(398568,44286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... das Pflaster bis zum Mittag seinen Job als Behandlung erledigt.'::text,'hat'::text,'erledigt'::text,'macht'::text,'Hör mal, angeblich hat das Pflaster bis zum Mittag seinen Job als Behandlung erledigt.'::text),
(398572,44286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, до обіду пластир уже ... свою справу як лікування.'::text,'зробить'::text,'зробить'::text,'робитиме'::text,'Слухай, кажуть, до обіду пластир уже зробить свою справу як лікування.'::text),
(398571,44286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer para la hora de comer la tirita ya ... su trabajo como tratamiento.'::text,'habrá hecho'::text,'hará'::text,'estará haciendo'::text,'Oye, al parecer para la hora de comer la tirita ya habrá hecho su trabajo como tratamiento.'::text),
(398570,44286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment d''ici le déjeuner, le pansement ... son travail de traitement.'::text,'aura fait'::text,'fera'::text,'sera en train de faire'::text,'Écoute, apparemment d''ici le déjeuner, le pansement aura fait son travail de traitement.'::text),
(398573,44286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan öğlene kadar yara bandı tedavi olarak işini ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor olacak'::text,'Dinle, anlaşılan öğlene kadar yara bandı tedavi olarak işini görmüş olacak.'::text),
(398574,44286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ebédre a sebtapasz ... a dolgát kezelésként.'::text,'elvégzi'::text,'el fogja végezni'::text,'végezni fogja'::text,'Figyelj, állítólag ebédre a sebtapasz elvégzi a dolgát kezelésként.'::text),
(398577,44287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei Sonnenuntergang ... du zehn Stunden auf diesem Trail unterwegs, mit Behandlung und allem, ehrlich ikonisch.'::text,'bist'::text,'bist'::text,'bist'::text,'Bei Sonnenuntergang bist du zehn Stunden auf diesem Trail unterwegs, mit Behandlung und allem, ehrlich ikonisch.'::text),
(398581,44287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця ти ... цією стежкою десять годин, з лікуванням і всім іншим, чесно, культово.'::text,'йтимеш'::text,'йтимеш'::text,'пройдеш'::text,'До заходу сонця ти йтимеш цією стежкою десять годин, з лікуванням і всім іншим, чесно, культово.'::text),
(398580,44287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al atardecer ... este sendero durante diez horas, tratamiento incluido, sinceramente icónico.'::text,'habrás estado caminando por'::text,'estarás caminando por'::text,'habrás caminado por'::text,'Al atardecer habrás estado caminando por este sendero durante diez horas, tratamiento incluido, sinceramente icónico.'::text),
(398579,44287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, tu ... ce sentier pendant dix heures, soins compris, franchement iconique.'::text,'auras arpenté'::text,'seras en train d''arpenter'::text,'auras parcouru'::text,'Au coucher du soleil, tu auras arpenté ce sentier pendant dix heures, soins compris, franchement iconique.'::text),
(398582,44287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu patikada on saat ..., tedavisiyle falan, açıkçası efsane.'::text,'yürümüş olacaksın'::text,'yürüyor olacaksın'::text,'yürümüş olacaksın'::text,'Gün batımına kadar bu patikada on saat yürümüş olacaksın, tedavisiyle falan, açıkçası efsane.'::text),
